                    <label className="text-[var(--text-secondary)] font-semibold">Overlay Opacity</label>
                    <span className="font-mono text-[var(--text)]">{activeSectionObj.overlayOpacity}%</span>
                  </div>
                  <input
                    type="range"
                    min="0"
                    max="100"
