  Sparkles,
} from "lucide-react";
import { loginSession } from "@/lib/auth";
import { PhoneInput } from "@/components/ui/phone-input";
import { repsiApi } from "@/lib/api";
import { motion, AnimatePresence } from "framer-motion";
