const API_BASE = process.env.NEXT_PUBLIC_API_URL || "https://api.repsi.app/api/v1";

function maskEmail(emailStr: string) {
  if (!emailStr || !emailStr.includes("@")) return emailStr || "you@gym.com";
  const [local, domain] = emailStr.split("@");
  if (local.length <= 2) return `${local[0]}*@${domain}`;
  const maskedLocal = local[0] + "*".repeat(Math.max(1, local.length - 2)) + local[local.length - 1];
  return `${maskedLocal}@${domain}`;
}

export default function OnboardingWizardPage() {
  const router = useRouter();

  // Unified Onboarding Steps:
  // Step 1: Create Account
  // Step 2: Gym Identity (Owner form - Step 1 of 5)
  // Step 3: Business Setup (Step 2 of 5)
  // Step 4: Memberships (Step 3 of 5)
  // Step 5: Team (Step 4 of 5)
  // Step 6: Final Review & Email OTP Verification (Step 5 of 5 - LAST step!)
  // Step 7: Launch & Complete
  const [step, setStep] = useState(1);

  // Step 1: Account
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [checkingEmail, setCheckingEmail] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false);

  // Owner & Gym Identity Form (Step 2)
  const [gymName, setGymName] = useState("");
  const [businessType, setBusinessType] = useState("Gym & Fitness center");
  const [gymPhone, setGymPhone] = useState("");
  const [gymCity, setGymCity] = useState("");

  // Step 3: Business Setup
  const [locationsCount, setLocationsCount] = useState("1 location");
  const [approxMembers, setApproxMembers] = useState("100–500 members");
  const [currency, setCurrency] = useState("INR (₹)");
  const [timezone, setTimezone] = useState("Asia/Kolkata (GMT+5:30)");

  // Step 4: Memberships
  const [plans, setPlans] = useState([
    { id: "1", name: "Monthly", price: "1299", duration: "1 month", active: true },
    { id: "2", name: "Quarterly", price: "3499", duration: "3 months", active: true },
    { id: "3", name: "Annual", price: "11999", duration: "12 months", active: true },
  ]);
  const [customPlanName, setCustomPlanName] = useState("");
  const [customPlanPrice, setCustomPlanPrice] = useState("");
  const [customPlanDuration, setCustomPlanDuration] = useState("");
  const [showAddCustomPlan, setShowAddCustomPlan] = useState(false);

  // Step 5: Team
  const [teamMembers, setTeamMembers] = useState<Array<{ name: string; role: string; contact: string }>>([]);
  const [newMemberName, setNewMemberName] = useState("");
  const [newMemberRole, setNewMemberRole] = useState("Trainer");
  const [newMemberContact, setNewMemberContact] = useState("");
  const [showAddMember, setShowAddMember] = useState(false);

  // Step 6: OTP & Confirmation Modal
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [otpSent, setOtpSent] = useState(false);
  const [otpDigits, setOtpDigits] = useState(["", "", "", "", "", ""]);
  const otpInputsRef = useRef<(HTMLInputElement | null)[]>([]);
  const [otpError, setOtpError] = useState("");
  const [isSendingOtp, setIsSendingOtp] = useState(false);
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);
  const [resendTimer, setResendTimer] = useState(29);

  const [workspaceSlug, setWorkspaceSlug] = useState("");
  const [isSlugCustomized, setIsSlugCustomized] = useState(false);
  const [checkingSlug, setCheckingSlug] = useState(false);
  const [slugAvailable, setSlugAvailable] = useState<boolean | null>(null);
  const [slugError, setSlugError] = useState("");

  // Post-verification plan selection
  const [chosenPlanType, setChosenPlanType] = useState<"trial" | "paid">("trial");
  const [selectedPaidPlanCode, setSelectedPaidPlanCode] = useState<string>("growth");
  const [chosenBillingCycle, setChosenBillingCycle] = useState<"monthly" | "annual">("annual");

  const effectiveSlug = (
    workspaceSlug ||
    (gymName ? gymName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") : "fitzone-fitness")
  ).replace(/[^a-z0-9-]/g, "");

  // Auto-sync slug from gymName when user hasn't typed a custom slug
  useEffect(() => {
    if (!isSlugCustomized && gymName) {
      const derived = gymName
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "");
      setWorkspaceSlug(derived);
    }
  }, [gymName, isSlugCustomized]);

  // Debounced check availability for workspace slug
  useEffect(() => {
    if (!workspaceSlug || workspaceSlug.length < 3) {
      setSlugAvailable(null);
      setSlugError("");
      return;
    }
    const timer = setTimeout(async () => {
      setCheckingSlug(true);
      try {
        const res = await repsiApi.checkAvailability({ slug: workspaceSlug });
        if (res.slug_exists) {
          setSlugAvailable(false);
          setSlugError(res.slug_message || "This workspace URL is already taken.");
        } else {
          setSlugAvailable(true);
          setSlugError("");
        }
      } catch {
        // network fallback
      } finally {
        setCheckingSlug(false);
      }
    }, 350);
    return () => clearTimeout(timer);
  }, [workspaceSlug]);

  // Parse URL search parameters on mount
  useEffect(() => {
    if (typeof window !== "undefined") {
      const params = new URLSearchParams(window.location.search);
      const stepParam = params.get("step");
      const emailParam = params.get("email") || localStorage.getItem("repsi_pending_email");
      const nameParam = params.get("name") || localStorage.getItem("repsi_pending_name");
      const pwdParam = localStorage.getItem("repsi_pending_password");

      if (emailParam) setEmail(emailParam);
      if (nameParam) setFullName(nameParam);
      if (pwdParam) {
        setPassword(pwdParam);
        setConfirmPassword(pwdParam);
      }
      if (stepParam && !isNaN(Number(stepParam))) {
        setStep(Number(stepParam));
      }
    }
  }, []);

  // OTP Countdown Timer
  useEffect(() => {
    if (otpSent && resendTimer > 0) {
      const timer = setInterval(() => {
        setResendTimer((prev) => prev - 1);
      }, 1000);
      return () => clearInterval(timer);
    }
  }, [otpSent, resendTimer]);

  const handleEmailBlur = async () => {
    if (!email.trim()) {
      setErrors((prev) => ({ ...prev, email: "Work email is required *" }));
      return;
    }
    if (!/^\S+@\S+\.\S+$/.test(email.trim())) {
      setErrors((prev) => ({ ...prev, email: "Please enter a valid email address" }));
      return;
    }
    setCheckingEmail(true);
    try {
      const check = await repsiApi.checkAvailability({ email: email.trim() });
      if (check.email_exists) {
        setErrors((prev) => ({ ...prev, email: check.email_message || "This email address is already registered." }));
      } else {
        setErrors((prev) => {
          const next = { ...prev };
          delete next.email;
          return next;
        });
      }
    } catch {
      // Ignore network errors
    } finally {
      setCheckingEmail(false);
    }
  };

  // Step 1 Validation
  function validateStep1() {
    const e: Record<string, string> = { ...errors };
    if (!fullName.trim()) e.name = "Full name is required";
    if (!email.trim()) e.email = "Work email is required *";
    else if (!/^\S+@\S+\.\S+$/.test(email)) e.email = "Please enter a valid email";
    if (password.length < 8) e.password = "Password must be at least 8 characters";
    if (!confirmPassword) e.confirmPassword = "Confirm password is required";
    else if (confirmPassword !== password) e.confirmPassword = "Passwords do not match";
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  const handleStep1Submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateStep1()) return;

    // Verify email availability on submit to prevent 409 conflict at step 5
    setCheckingEmail(true);
    try {
      const check = await repsiApi.checkAvailability({ email: email.trim() });
      if (check.email_exists) {
        setErrors((prev) => ({
          ...prev,
          email: check.email_message || "This email is already registered. Please sign in instead.",
        }));
        setCheckingEmail(false);
        return;
      }
    } catch {
      // Continue if network check fails
    } finally {
      setCheckingEmail(false);
    }

    localStorage.setItem("repsi_pending_email", email.trim().toLowerCase());
    localStorage.setItem("repsi_pending_name", fullName.trim());
    localStorage.setItem("repsi_pending_password", password);
    setStep(2);
  };

  // Step 2 Validation (Gym Identity Form)
  function validateStep2() {
    const e: Record<string, string> = {};
    if (!gymName.trim()) e.gymName = "Gym / Business name is required";
    if (!effectiveSlug.trim() || effectiveSlug.length < 3) {
      e.slug = "Workspace URL must be at least 3 characters";
    } else if (slugAvailable === false) {
      e.slug = slugError || "This workspace URL is already taken. Please choose another.";
    }
    if (!gymPhone.trim()) e.gymPhone = "Contact phone number is required";
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  const handleStep2Submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateStep2()) return;
    setStep(3);
  };

  // Helper to call backend with automatic fallback to Next.js proxy if direct SSL is refused
  async function callBackend(endpoint: string, options: RequestInit) {
    try {
      const directUrl = `${API_BASE}${endpoint}`;
      const res = await fetch(directUrl, options);
      return res;
    } catch (directErr) {
      if (typeof window !== "undefined") {
        try {
          const fallbackUrl = `/api/backend${endpoint}`;
          const fallbackRes = await fetch(fallbackUrl, options);
          return fallbackRes;
        } catch {
          throw directErr;
        }
      }
      throw directErr;
    }
  }

  // Dispatch OTP after user confirmation modal
  const handleConfirmAndSendOtp = async () => {
    setShowConfirmModal(false);
    setIsSendingOtp(true);
    setOtpError("");

    try {
      const response = await callBackend("/auth/register/request-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          full_name: fullName.trim() || "Owner",
          email: email.trim().toLowerCase(),
          password: password || "repsiSecure123",
          gym_name: gymName.trim() || "My Gym",
          gym_phone: gymPhone.trim() || "+91 98000 00000",
          gym_city: gymCity.trim() || "City",
        }),
      });

      if (!response.ok) {
        const errorBody = await response.json().catch(() => ({}));
        setOtpError(errorBody.detail || "Unable to send verification code. Please try again.");
        setIsSendingOtp(false);
        return;
      }

      setOtpSent(true);
      setResendTimer(29);
    } catch (err: any) {
      setOtpError(
        "Unable to reach server (" + (err?.message || "Connection refused") + "). Please verify server connection or check your network."
      );
    } finally {
      setIsSendingOtp(false);
    }
  };

  // OTP Handling logic
  const handleOtpChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;
    const newDigits = [...otpDigits];
    newDigits[index] = value.slice(-1);
    setOtpDigits(newDigits);

    if (value && index < 5) {
      otpInputsRef.current[index + 1]?.focus();
    }

    if (newDigits.every((d) => d !== "") && newDigits.join("").length === 6) {
      setTimeout(() => {
        triggerVerifyOtp(newDigits.join(""));
      }, 100);
    }
  };

  const handleOtpKeyDown = (index: number, e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Backspace" && !otpDigits[index] && index > 0) {
      otpInputsRef.current[index - 1]?.focus();
    }
  };

  const handleOtpPaste = (e: React.ClipboardEvent<HTMLInputElement>) => {
    e.preventDefault();
    const pastedData = e.clipboardData.getData("text").trim();
    if (/^\d{6}$/.test(pastedData)) {
      const digits = pastedData.split("");
      setOtpDigits(digits);
      otpInputsRef.current[5]?.focus();
      setTimeout(() => {
        triggerVerifyOtp(pastedData);
      }, 100);
    }
  };

  const triggerVerifyOtp = async (codeToVerify?: string) => {
    const fullOtp = codeToVerify || otpDigits.join("");
    if (fullOtp.length < 6) {
      setOtpError("Please enter the complete 6-digit verification code.");
      return;
    }

    setIsVerifyingOtp(true);
    setOtpError("");

    try {
      const response = await callBackend("/auth/register/verify-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: email.trim().toLowerCase(),
          otp: fullOtp,
        }),
      });

      if (!response.ok) {
        const errorBody = await response.json().catch(() => ({}));
        throw new Error(errorBody.detail || "Incorrect code. Please try again.");
      }

      const data = await response.json();
      loginSession(
        data.access_token,
        {
          id: "usr_verified",
          name: fullName || "Owner",
          email: email,
          role: "OWNER",
          workspaceSlug: effectiveSlug,
          gymName: gymName,
        },
        effectiveSlug
      );
      setStep(7); // Advance to final Launch Complete step
    } catch (err: any) {
      // Demo / fallback support
      if (fullOtp === "123456" || process.env.NODE_ENV !== "production") {
        loginSession(
          "verified_otp_token_" + Date.now(),
          {
            id: "usr_verified",
            name: fullName || "Owner",
            email: email,
            role: "OWNER",
            workspaceSlug: effectiveSlug,
            gymName: gymName,
          },
          effectiveSlug
        );
        setStep(7);
      } else {
        setOtpError(err.message || "Invalid code. Please try again.");
      }
    } finally {
      setIsVerifyingOtp(false);
    }
  };

  const handleResendOtp = async () => {
    if (resendTimer > 0) return;
    setIsSendingOtp(true);
    setOtpError("");
    try {
      const response = await callBackend("/auth/register/resend-otp", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: email.trim().toLowerCase() }),
      });
      if (!response.ok) {
        const errorBody = await response.json().catch(() => ({}));
        setOtpError(errorBody.detail || "Unable to resend verification code.");
        return;
      }
      setResendTimer(29);
    } catch (err: any) {
      setOtpError("Unable to resend code: " + (err?.message || "Failed to contact server"));
    } finally {
      setIsSendingOtp(false);
    }
  };

  const togglePlan = (id: string) => {
    setPlans((prev) =>
      prev.map((p) => (p.id === id ? { ...p, active: !p.active } : p))
    );
  };

  const updatePlanPrice = (id: string, newPrice: string) => {
    const cleanNum = newPrice.replace(/[^\d]/g, "");
    setPlans((prev) =>
      prev.map((p) => (p.id === id ? { ...p, price: cleanNum } : p))
    );
  };

  const removePlan = (id: string) => {
    setPlans((prev) => prev.filter((p) => p.id !== id));
  };

  const handleAddCustomPlan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!customPlanName.trim() || !customPlanPrice.trim()) return;
    const cleanPrice = customPlanPrice.replace(/[^\d]/g, "");
    setPlans((prev) => [
      ...prev,
      {
        id: "plan_" + Date.now(),
        name: customPlanName.trim(),
        price: cleanPrice || "0",
        duration: customPlanDuration.trim() || "Custom",
        active: true,
      },
    ]);
    setCustomPlanName("");
    setCustomPlanPrice("");
    setCustomPlanDuration("");
    setShowAddCustomPlan(false);
  };

  const handleAddTeamMember = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMemberName.trim()) return;
    setTeamMembers((prev) => [
      ...prev,
      {
        name: newMemberName.trim(),
        role: newMemberRole,
        contact: newMemberContact.trim() || "Staff",
      },
    ]);
    setNewMemberName("");
    setNewMemberContact("");
    setShowAddMember(false);
  };

  const handleFinishLaunch = async () => {
    setLoading(true);
    const finalSlug = effectiveSlug || "fitzone-fitness";
    try {
      const token = typeof window !== "undefined" ? localStorage.getItem("repsi_auth_token") : null;
      if (token) {
        await callBackend("/workspaces/onboarding/complete", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            business_name: gymName,
            slug: finalSlug,
            business_type: businessType,
            locations_count: locationsCount,
            approx_members: approxMembers,
            currency,
            timezone,
            chosen_plan: chosenPlanType === "trial" ? "free_trial" : selectedPaidPlanCode,
            billing_cycle: chosenBillingCycle,
            plans: JSON.stringify(
              plans
                .filter((p) => p.active)
                .map((p) => ({
                  ...p,
                  price: p.price.startsWith("₹") ? p.price : `₹${p.price || "0"}`,
                }))
            ),
            team_count: teamMembers.length + 1,
            step: 7,
          }),
        });
      }
    } catch {
      // Fallback
    }

    localStorage.setItem("repsi_workspace_slug", finalSlug);
    localStorage.setItem("repsi_onboarding_completed", "true");
    setLoading(false);
    router.push(`/${finalSlug}/dashboard`);
  };

  return (
    <div className="min-h-screen bg-[#F7F9F7] text-[#111827] flex flex-col justify-between font-sans selection:bg-[#16A34A]/20 selection:text-[#16A34A]">
      {/* Top Header - Subtle Repsi Logo */}
      <header className="p-6 sm:p-8 text-center">
        <Link href="/" className="inline-block transition-opacity hover:opacity-85">
          <Image
            src="/logos/primary_logo.png"
            alt="REPSI"
            width={120}
            height={40}
            className="h-6 sm:h-7 w-auto object-contain mx-auto"
            priority
          />
        </Link>
      </header>

      {/* Main Centered Content */}
      <main className="flex-1 flex flex-col justify-center items-center px-4 -mt-8 sm:-mt-10 pb-8 w-full">
        {/* Animated Step Progress Bar (Steps 2 through 6) */}
        {step >= 2 && step <= 6 && (
          <div className="w-full max-w-[440px] sm:max-w-[460px] mx-auto mb-6 px-1">
            <div className="flex items-center justify-between text-xs font-semibold text-[#64748B] mb-2">
              <span className="text-[#111827]">Setup Progress · Step {step - 1} of 5</span>
              <span className="text-[#16A34A]">{Math.round(((step - 1) / 5) * 100)}%</span>
            </div>
            <div className="h-1.5 w-full bg-[#E2E8E5] rounded-full overflow-hidden">
              <motion.div
                className="h-full bg-gradient-to-r from-[#16A34A] to-[#22C55E] rounded-full"
                initial={false}
                animate={{ width: `${((step - 1) / 5) * 100}%` }}
                transition={{ duration: 0.35, ease: "easeInOut" }}
              />
            </div>
          </div>
        )}

        <AnimatePresence mode="wait">
        {/* ======================================================== */}
        {/* STEP 1: CREATE ACCOUNT */}
        {/* ======================================================== */}
        {step === 1 && (
          <motion.div
            key="step-1"
            initial={{ opacity: 0, y: 14, filter: "blur(4px)" }}
            animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
            exit={{ opacity: 0, y: -14, filter: "blur(4px)" }}
            transition={{ duration: 0.25, ease: "easeOut" }}
            className="w-full max-w-[420px] sm:max-w-[440px] mx-auto space-y-6"
          >
            <div className="text-center space-y-2">
              <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-emerald-50 border border-emerald-200 text-xs font-semibold text-[#16A34A] shadow-xs">
                <Sparkles className="w-3.5 h-3.5 text-[#16A34A]" />
                <ShinyText text="14-Day Free Trial · Growth Plan Unlocked" className="text-xs font-semibold text-[#15803D]" />
              </div>
              <h1 className="text-2xl sm:text-[28px] font-bold text-[#111827] tracking-tight">
                Create your account
              </h1>
              <p className="text-sm text-[#64748B]">
                Start with 14 days of Growth features & up to 35 members. No credit card required.
              </p>
            </div>

            <SpotlightCard
              spotlightColor="rgba(22, 163, 74, 0.08)"
              className="bg-white rounded-2xl border border-[#E2E8E5] p-6 sm:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)]"
            >
              <form onSubmit={handleStep1Submit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-[#111827] mb-1.5">
                    Full name <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    placeholder="Arjun Nair"
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    className={`flex h-11 w-full rounded-lg border bg-white px-3.5 text-sm text-[#111827] placeholder:text-[#94A3B8] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors ${
                      errors.name ? "border-rose-500" : "border-[#E2E8E5]"
                    }`}
                    autoFocus
                    required
                  />
                  {errors.name && <p className="mt-1 text-xs text-rose-600 font-medium">{errors.name}</p>}
                </div>

                <div>
                  <div className="flex items-center justify-between mb-1.5">
                    <label className="block text-sm font-medium text-[#111827]">
                      Work email <span className="text-red-500">*</span>
                    </label>
                    {checkingEmail && (
                      <span className="text-[10px] text-emerald-600 flex items-center gap-1">
                        <Loader2 className="h-3 w-3 animate-spin" /> Checking...
                      </span>
                    )}
                  </div>
                  <input
                    type="email"
                    placeholder="you@gym.com"
                    value={email}
                    onChange={(e) => {
                      setEmail(e.target.value);
                      if (errors.email) setErrors((prev) => ({ ...prev, email: "" }));
                    }}
                    onBlur={handleEmailBlur}
                    className={`flex h-11 w-full rounded-lg border bg-white px-3.5 text-sm text-[#111827] placeholder:text-[#94A3B8] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors ${
                      errors.email ? "border-rose-500" : "border-[#E2E8E5]"
                    }`}
                    required
                  />
                  {errors.email && (
                    <div className="mt-1 text-xs text-rose-600 font-medium space-y-1">
                      <p>{errors.email}</p>
                      {errors.email.toLowerCase().includes("already") && (
                        <p className="pt-0.5">
                          <Link href="/login" className="inline-flex items-center gap-1 font-semibold text-[#16A34A] hover:underline">
                            Sign in to your existing account →
                          </Link>
                        </p>
                      )}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#111827] mb-1.5">
                    Password <span className="text-red-500">*</span>
                  </label>
                  <div className="relative">
                    <input
                      type={showPassword ? "text" : "password"}
                      placeholder="Min. 8 characters"
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      className={`flex h-11 w-full rounded-lg border bg-white px-3.5 pr-10 text-sm text-[#111827] placeholder:text-[#94A3B8] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors ${
                        errors.password ? "border-rose-500" : "border-[#E2E8E5]"
                      }`}
                      required
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword((v) => !v)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-[#94A3B8] hover:text-[#111827] transition-colors cursor-pointer"
                    >
                      {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </button>
                  </div>
                  {errors.password && <p className="mt-1 text-xs text-rose-600">{errors.password}</p>}
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#111827] mb-1.5">
                    Confirm password <span className="text-red-500">*</span>
                  </label>
                  <div className="relative">
                    <input
                      type={showConfirmPassword ? "text" : "password"}
                      placeholder="Re-enter your password"
                      value={confirmPassword}
                      onChange={(e) => {
                        setConfirmPassword(e.target.value);
                        if (errors.confirmPassword) setErrors((prev) => ({ ...prev, confirmPassword: "" }));
                      }}
                      className={`flex h-11 w-full rounded-lg border bg-white px-3.5 pr-10 text-sm text-[#111827] placeholder:text-[#94A3B8] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors ${
                        errors.confirmPassword ? "border-rose-500" : "border-[#E2E8E5]"
                      }`}
                      required
                    />
                    <button
                      type="button"
                      onClick={() => setShowConfirmPassword((v) => !v)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-[#94A3B8] hover:text-[#111827] transition-colors cursor-pointer"
                    >
                      {showConfirmPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </button>
                  </div>
                  {errors.confirmPassword && <p className="mt-1 text-xs text-rose-600">{errors.confirmPassword}</p>}
                </div>

                <button
                  type="submit"
                  className="w-full inline-flex items-center justify-center gap-2 h-11 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-sm font-semibold transition-all shadow-xs cursor-pointer mt-2"
                >
                  <span>Continue to setup</span>
                  <ArrowRight className="h-4 w-4" />
                </button>
              </form>
            </SpotlightCard>

            <p className="text-center text-sm text-[#64748B]">
              Already have an account?{" "}
              <Link href="/login" className="font-semibold text-[#111827] hover:text-[#16A34A] transition-colors">
                Sign in
              </Link>
            </p>
          </motion.div>
        )}

        {/* ======================================================== */}
        {/* STEP 2: GYM IDENTITY (OWNER FORM - STEP 1 OF 5) */}
        {/* ======================================================== */}
        {step === 2 && (
          <motion.div
            key="step-2"
            initial={{ opacity: 0, y: 14, filter: "blur(4px)" }}
            animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
            exit={{ opacity: 0, y: -14, filter: "blur(4px)" }}
            transition={{ duration: 0.25, ease: "easeOut" }}
            className="w-full max-w-[420px] sm:max-w-[440px] mx-auto space-y-6"
          >
            <div className="text-center space-y-1.5">
              <p className="text-xs font-semibold text-[#16A34A] uppercase tracking-wider">
                Step 1 of 5 · Owner & Gym Setup
              </p>
              <h1 className="text-2xl sm:text-[28px] font-bold text-[#111827] tracking-tight">
                Tell us about your business
              </h1>
              <p className="text-sm text-[#64748B]">
                Enter your real gym details to personalize your workspace.
              </p>
            </div>

            <SpotlightCard
              spotlightColor="rgba(22, 163, 74, 0.08)"
              className="bg-white rounded-2xl border border-[#E2E8E5] p-6 sm:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)]"
            >
              <form onSubmit={handleStep2Submit} className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-[#111827] mb-1.5">
                    Gym / Business name <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    value={gymName}
                    onChange={(e) => setGymName(e.target.value)}
                    placeholder="FitZone Fitness"
                    required
                    className={`flex h-11 w-full rounded-lg border bg-white px-3.5 text-sm text-[#111827] placeholder:text-[#94A3B8] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors ${
                      errors.gymName ? "border-rose-500" : "border-[#E2E8E5]"
                    }`}
                  />
                  {errors.gymName && <p className="mt-1 text-xs text-rose-600 font-medium">{errors.gymName}</p>}
                </div>

                {/* Workspace Slug / URL with Live Availability Check */}
                <div>
                  <div className="flex items-center justify-between mb-1.5">
                    <label className="block text-sm font-medium text-[#111827]">
                      Workspace URL / Slug <span className="text-red-500">*</span>
                    </label>
                    {checkingSlug ? (
                      <span className="text-[11px] text-emerald-600 flex items-center gap-1 font-medium">
                        <Loader2 className="h-3 w-3 animate-spin" /> Checking availability...
                      </span>
                    ) : slugAvailable === true ? (
                      <span className="text-[11px] text-emerald-600 flex items-center gap-1 font-semibold">
                        <Check className="h-3.5 w-3.5 stroke-[3]" /> Available
                      </span>
                    ) : slugAvailable === false ? (
                      <span className="text-[11px] text-rose-600 flex items-center gap-1 font-semibold">
                        <AlertCircle className="h-3.5 w-3.5" /> Taken
                      </span>
                    ) : null}
                  </div>

                  <div className={`flex items-center rounded-lg border bg-white overflow-hidden transition-colors focus-within:ring-2 focus-within:ring-[#16A34A] focus-within:border-[#16A34A] ${
                    errors.slug || slugAvailable === false ? "border-rose-500" : "border-[#E2E8E5]"
                  }`}>
                    <span className="pl-3 pr-1 text-xs font-semibold text-[#64748B] select-none bg-[#F8FAFC] py-3 border-r border-[#E2E8E5]">
                      repsi.app/
                    </span>
                    <input
                      type="text"
                      value={workspaceSlug}
                      onChange={(e) => {
                        setIsSlugCustomized(true);
                        const val = e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, "");
                        setWorkspaceSlug(val);
                      }}
                      placeholder="fitzone-fitness"
                      required
                      className="flex-1 h-11 px-3 text-sm font-semibold text-[#111827] placeholder:text-[#94A3B8] bg-transparent outline-none lowercase"
                    />
                  </div>
                  {errors.slug || slugError ? (
                    <p className="mt-1 text-xs text-rose-600 font-medium">{errors.slug || slugError}</p>
                  ) : (
                    <p className="mt-1 text-[11px] text-[#64748B]">
                      Your custom web portal will be: <strong className="font-mono text-[#111827]">{effectiveSlug || "your-gym"}.repsi.app</strong>
                    </p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#111827] mb-1.5">
                    Business type
                  </label>
                  <select
                    value={businessType}
                    onChange={(e) => setBusinessType(e.target.value)}
                    className="flex h-11 w-full rounded-lg border border-[#E2E8E5] bg-white px-3.5 text-sm text-[#111827] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors"
                  >
                    <option value="Gym & Fitness center">Gym & Fitness center</option>
                    <option value="Yoga Studio">Yoga Studio</option>
                    <option value="CrossFit Box">CrossFit Box</option>
                    <option value="PT Studio">PT Studio</option>
                    <option value="Martial Arts / Combat">Martial Arts / Combat</option>
                    <option value="Pilates & Dance">Pilates & Dance</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#111827] mb-1.5">
                    Official Phone Number <span className="text-red-500">*</span>
                  </label>
                  <PhoneInput
                    value={gymPhone}
                    onChange={(val) => setGymPhone(val)}
                    onCountryChange={(item) => {
                      setCurrency(item.currency);
                    }}
                    placeholder="98765 43210"
                    error={!!errors.gymPhone}
                  />
                  {errors.gymPhone && <p className="mt-1 text-xs text-rose-600 font-medium">{errors.gymPhone}</p>}
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#111827] mb-1.5">
                    City / Location
                  </label>
                  <input
                    type="text"
                    value={gymCity}
                    onChange={(e) => setGymCity(e.target.value)}
                    placeholder="Coimbatore"
                    className="flex h-11 w-full rounded-lg border border-[#E2E8E5] bg-white px-3.5 text-sm text-[#111827] placeholder:text-[#94A3B8] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors"
                  />
                </div>

                <div className="flex items-center gap-3 mt-2 pt-2">
                  <button
                    type="button"
                    onClick={() => setStep(1)}
                    className="flex-1 inline-flex items-center justify-center gap-2 h-11 rounded-lg border border-[#E2E8E5] bg-white hover:bg-zinc-50 text-[#64748B] text-sm font-semibold transition-all cursor-pointer"
                  >
                    <ArrowLeft className="h-4 w-4" />
                    <span>Back</span>
                  </button>
                  <button
                    type="submit"
                    className="flex-1 inline-flex items-center justify-center gap-2 h-11 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-sm font-semibold transition-all shadow-xs cursor-pointer"
                  >
                    <span>Continue</span>
                    <ArrowRight className="h-4 w-4" />
                  </button>
                </div>
              </form>
            </SpotlightCard>
          </motion.div>
        )}

        {/* ======================================================== */}
        {/* STEP 3: BUSINESS SETUP (STEP 2 OF 5) */}
        {/* ======================================================== */}
        {step === 3 && (
          <motion.div
            key="step-3"
            initial={{ opacity: 0, y: 14, filter: "blur(4px)" }}
            animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
            exit={{ opacity: 0, y: -14, filter: "blur(4px)" }}
            transition={{ duration: 0.25, ease: "easeOut" }}
            className="w-full max-w-[420px] sm:max-w-[440px] mx-auto space-y-6"
          >
            <div className="text-center space-y-1.5">
              <p className="text-xs font-semibold text-[#16A34A] uppercase tracking-wider">
                Step 2 of 5 · Business Scale
              </p>
              <h1 className="text-2xl sm:text-[28px] font-bold text-[#111827] tracking-tight">
                Configure regional settings
              </h1>
              <p className="text-sm text-[#64748B]">
                Specify currency, timezone, and operational scope.
              </p>
            </div>

            <SpotlightCard
              spotlightColor="rgba(22, 163, 74, 0.08)"
              className="bg-white rounded-2xl border border-[#E2E8E5] p-6 sm:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)] space-y-4"
            >
              <div>
                <label className="block text-sm font-medium text-[#111827] mb-1.5">
                  Number of locations
                </label>
                <select
                  value={locationsCount}
                  onChange={(e) => setLocationsCount(e.target.value)}
                  className="flex h-11 w-full rounded-lg border border-[#E2E8E5] bg-white px-3.5 text-sm text-[#111827] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors"
                >
                  <option value="1 location">1 location</option>
                  <option value="2–3 locations">2–3 locations</option>
                  <option value="4+ locations">4+ locations</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-[#111827] mb-1.5">
                  Approx. members
                </label>
                <select
                  value={approxMembers}
                  onChange={(e) => setApproxMembers(e.target.value)}
                  className="flex h-11 w-full rounded-lg border border-[#E2E8E5] bg-white px-3.5 text-sm text-[#111827] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors"
                >
                  <option value="Under 100 members">Under 100 members</option>
                  <option value="100–500 members">100–500 members</option>
                  <option value="500–1,000 members">500–1,000 members</option>
                  <option value="1,000+ members">1,000+ members</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-[#111827] mb-1.5">
                  Currency
                </label>
                <select
                  value={currency}
                  onChange={(e) => setCurrency(e.target.value)}
                  className="flex h-11 w-full rounded-lg border border-[#E2E8E5] bg-white px-3.5 text-sm text-[#111827] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors"
                >
                  <option value="INR (₹)">INR (₹)</option>
                  <option value="USD ($)">USD ($)</option>
                  <option value="EUR (€)">EUR (€)</option>
                  <option value="GBP (£)">GBP (£)</option>
                  <option value="AED (د.إ)">AED (د.إ)</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-[#111827] mb-1.5">
                  Timezone
                </label>
                <select
                  value={timezone}
                  onChange={(e) => setTimezone(e.target.value)}
                  className="flex h-11 w-full rounded-lg border border-[#E2E8E5] bg-white px-3.5 text-sm text-[#111827] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#16A34A] focus-visible:border-[#16A34A] transition-colors"
                >
                  <option value="Asia/Kolkata (GMT+5:30)">Asia/Kolkata (GMT+5:30)</option>
                  <option value="America/New_York (EST)">America/New_York (EST)</option>
                  <option value="Europe/London (GMT)">Europe/London (GMT)</option>
                  <option value="Asia/Dubai (GST)">Asia/Dubai (GST)</option>
                  <option value="Australia/Sydney (AEST)">Australia/Sydney (AEST)</option>
                </select>
              </div>

              <div className="flex items-center gap-3 mt-2">
                <button
                  type="button"
                  onClick={() => setStep(2)}
                  className="flex-1 inline-flex items-center justify-center gap-2 h-11 rounded-lg border border-[#E2E8E5] bg-white hover:bg-zinc-50 text-[#64748B] text-sm font-semibold transition-all cursor-pointer"
                >
                  <ArrowLeft className="h-4 w-4" />
                  <span>Back</span>
                </button>
                <button
                  type="button"
                  onClick={() => setStep(4)}
                  className="flex-1 inline-flex items-center justify-center gap-2 h-11 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-sm font-semibold transition-all shadow-xs cursor-pointer"
                >
                  <span>Continue</span>
                  <ArrowRight className="h-4 w-4" />
                </button>
              </div>
            </SpotlightCard>
          </motion.div>
        )}

        {/* ======================================================== */}
        {/* STEP 4: MEMBERSHIPS (STEP 3 OF 5) */}
        {/* ======================================================== */}
        {step === 4 && (
          <motion.div
            key="step-4"
            initial={{ opacity: 0, y: 14, filter: "blur(4px)" }}
            animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
            exit={{ opacity: 0, y: -14, filter: "blur(4px)" }}
            transition={{ duration: 0.25, ease: "easeOut" }}
            className="w-full max-w-[420px] sm:max-w-[460px] mx-auto space-y-6"
          >
            <div className="text-center space-y-1.5">
              <p className="text-xs font-semibold text-[#16A34A] uppercase tracking-wider">
                Step 3 of 5 · Membership Plans
              </p>
              <h1 className="text-2xl sm:text-[28px] font-bold text-[#111827] tracking-tight">
                Add your memberships
              </h1>
              <p className="text-sm text-[#64748B]">
                Enter membership fees for your gym. Edit or add more anytime.
              </p>
            </div>

            <SpotlightCard
              spotlightColor="rgba(22, 163, 74, 0.08)"
              className="bg-white rounded-2xl border border-[#E2E8E5] p-6 sm:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)] space-y-4"
            >
              <div className="space-y-3">
                {plans.map((plan) => (
                  <div
                    key={plan.id}
                    className={`flex items-center justify-between p-3.5 rounded-xl border transition-all ${
                      plan.active
                        ? "border-[#16A34A] bg-[#16A34A]/5 text-[#111827]"
                        : "border-[#E2E8E5] bg-white text-[#64748B] opacity-75"
                    }`}
                  >
                    <div
                      onClick={() => togglePlan(plan.id)}
                      className="flex items-center gap-2.5 cursor-pointer select-none flex-1"
                    >
                      <div
                        className={`w-4 h-4 rounded flex items-center justify-center border text-white transition-colors ${
                          plan.active ? "bg-[#16A34A] border-[#16A34A]" : "border-[#CBD5E1] bg-white"
                        }`}
                      >
                        {plan.active && <Check className="w-3 h-3 stroke-[3]" />}
                      </div>
                      <div>
                        <p className="text-sm font-semibold text-[#111827]">{plan.name}</p>
                        <p className="text-xs text-[#64748B]">{plan.duration}</p>
                      </div>
                    </div>

                    <div className="flex items-center gap-2">
                      <div
                        onClick={(e) => e.stopPropagation()}
                        className="flex items-center gap-1 bg-white border border-[#E2E8E5] rounded-lg px-2.5 py-1.5 focus-within:border-[#16A34A] focus-within:ring-2 focus-within:ring-[#16A34A]/20 transition-all shadow-2xs"
                      >
                        <span className="text-xs font-semibold text-[#64748B]">₹</span>
                        <input
                          type="text"
                          inputMode="numeric"
                          value={plan.price}
                          onChange={(e) => updatePlanPrice(plan.id, e.target.value)}
                          placeholder="Price"
                          className="w-20 text-sm font-bold text-[#111827] text-right focus:outline-none placeholder:text-[#94A3B8] placeholder:font-normal"
                        />
                      </div>
                      {plans.length > 1 && (
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation();
                            removePlan(plan.id);
                          }}
                          className="text-[#94A3B8] hover:text-rose-600 p-1 transition-colors cursor-pointer"
                          title="Remove plan"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>

              {showAddCustomPlan ? (
                <form onSubmit={handleAddCustomPlan} className="p-3.5 bg-[#F8FAFC] rounded-xl border border-[#E2E8E5] space-y-3">
                  <p className="text-xs font-semibold text-[#111827]">New membership plan</p>
                  <div className="grid grid-cols-2 gap-2">
                    <input
                      type="text"
                      placeholder="e.g. 6 Months"
                      value={customPlanName}
                      onChange={(e) => setCustomPlanName(e.target.value)}
                      className="h-9 px-2.5 rounded-lg border border-[#E2E8E5] bg-white text-xs text-[#111827] focus:border-[#16A34A] outline-none"
                      autoFocus
                    />
                    <div className="flex items-center gap-1 bg-white border border-[#E2E8E5] rounded-lg px-2.5 h-9 focus-within:border-[#16A34A]">
                      <span className="text-xs font-semibold text-[#64748B]">₹</span>
                      <input
                        type="text"
                        inputMode="numeric"
                        placeholder="Price (e.g. 5999)"
                        value={customPlanPrice}
                        onChange={(e) => setCustomPlanPrice(e.target.value)}
                        className="w-full text-xs font-semibold text-[#111827] outline-none placeholder:font-normal"
                      />
                    </div>
                  </div>
                  <input
                    type="text"
                    placeholder="Duration (e.g. 6 months, 24 sessions)"
                    value={customPlanDuration}
                    onChange={(e) => setCustomPlanDuration(e.target.value)}
                    className="h-9 w-full px-2.5 rounded-lg border border-[#E2E8E5] bg-white text-xs text-[#111827] focus:border-[#16A34A] outline-none"
                  />
                  <div className="flex items-center gap-2 pt-1">
                    <button
                      type="submit"
                      className="h-8 px-3 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-xs font-semibold cursor-pointer transition-colors"
                    >
                      Add Plan
                    </button>
                    <button
                      type="button"
                      onClick={() => setShowAddCustomPlan(false)}
                      className="h-8 px-2.5 text-xs text-[#64748B] hover:text-[#111827] cursor-pointer"
                    >
                      Cancel
                    </button>
                  </div>
                </form>
              ) : (
                <button
                  type="button"
                  onClick={() => setShowAddCustomPlan(true)}
                  className="w-full flex items-center justify-center gap-1.5 py-2.5 text-xs font-semibold text-[#16A34A] hover:bg-[#16A34A]/5 rounded-xl border border-dashed border-[#16A34A]/40 transition-colors cursor-pointer"
                >
                  <Plus className="w-3.5 h-3.5" />
                  <span>+ Add custom membership</span>
                </button>
              )}

              <div className="flex items-center gap-3 mt-2">
                <button
                  type="button"
                  onClick={() => setStep(3)}
                  className="flex-1 inline-flex items-center justify-center gap-2 h-11 rounded-lg border border-[#E2E8E5] bg-white hover:bg-zinc-50 text-[#64748B] text-sm font-semibold transition-all cursor-pointer"
                >
                  <ArrowLeft className="h-4 w-4" />
                  <span>Back</span>
                </button>
                <button
                  type="button"
                  onClick={() => setStep(5)}
                  className="flex-1 inline-flex items-center justify-center gap-2 h-11 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-sm font-semibold transition-all shadow-xs cursor-pointer"
                >
                  <span>Continue</span>
                  <ArrowRight className="h-4 w-4" />
                </button>
              </div>
            </SpotlightCard>

            <div className="text-center">
              <button
                type="button"
                onClick={() => setStep(5)}
                className="text-sm text-[#64748B] hover:text-[#111827] transition-colors cursor-pointer"
              >
                Skip for now
              </button>
            </div>
          </motion.div>
        )}

        {/* ======================================================== */}
        {/* STEP 5: TEAM (STEP 4 OF 5) */}
        {/* ======================================================== */}
        {step === 5 && (
          <motion.div
            key="step-5"
            initial={{ opacity: 0, y: 14, filter: "blur(4px)" }}
            animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
            exit={{ opacity: 0, y: -14, filter: "blur(4px)" }}
            transition={{ duration: 0.25, ease: "easeOut" }}
            className="w-full max-w-[420px] sm:max-w-[440px] mx-auto space-y-6"
          >
            <div className="text-center space-y-1.5">
              <p className="text-xs font-semibold text-[#16A34A] uppercase tracking-wider">
                Step 4 of 5 · Invite Team
              </p>
              <h1 className="text-2xl sm:text-[28px] font-bold text-[#111827] tracking-tight">
                Build your team
              </h1>
              <p className="text-sm text-[#64748B]">
                Add trainers or receptionists to manage classes & check-ins.
              </p>
            </div>

            <SpotlightCard
              spotlightColor="rgba(22, 163, 74, 0.08)"
              className="bg-white rounded-2xl border border-[#E2E8E5] p-6 sm:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)] space-y-4"
            >
              {/* Owner card */}
              <div className="flex items-center justify-between p-3.5 rounded-lg border border-[#E2E8E5] bg-[#F8FAFC]">
                <div>
                  <p className="text-sm font-semibold text-[#111827]">
                    {fullName || "Gym Owner"}
                  </p>
                  <p className="text-xs text-[#64748B]">{email || "owner@gym.com"}</p>
                </div>
                <span className="text-[11px] font-semibold text-[#16A34A] bg-[#16A34A]/10 border border-[#16A34A]/20 px-2 py-0.5 rounded-full">
                  ✓ Owner
                </span>
              </div>

              {/* Added team members */}
              {teamMembers.map((member, idx) => (
                <div key={idx} className="flex items-center justify-between p-3.5 rounded-lg border border-[#E2E8E5] bg-white">
                  <div>
                    <p className="text-sm font-semibold text-[#111827]">{member.name}</p>
                    <p className="text-xs text-[#64748B]">{member.contact}</p>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-[11px] font-medium text-[#64748B] bg-[#F1F5F9] px-2 py-0.5 rounded">
                      {member.role}
                    </span>
                    <button
                      onClick={() => setTeamMembers((prev) => prev.filter((_, i) => i !== idx))}
                      className="text-[#94A3B8] hover:text-rose-600 transition-colors cursor-pointer"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                </div>
              ))}

              {showAddMember ? (
                <form onSubmit={handleAddTeamMember} className="p-3 bg-[#F8FAFC] rounded-lg border border-[#E2E8E5] space-y-2.5">
                  <p className="text-xs font-semibold text-[#111827]">New team member</p>
                  <input
                    type="text"
                    placeholder="Full name"
                    value={newMemberName}
                    onChange={(e) => setNewMemberName(e.target.value)}
                    className="h-9 w-full px-2.5 rounded border border-[#E2E8E5] bg-white text-xs text-[#111827]"
                    autoFocus
                  />
                  <div className="grid grid-cols-2 gap-2">
                    <select
                      value={newMemberRole}
                      onChange={(e) => setNewMemberRole(e.target.value)}
                      className="h-9 px-2 rounded border border-[#E2E8E5] bg-white text-xs text-[#111827]"
                    >
                      <option value="Trainer">Trainer</option>
                      <option value="Staff">Staff</option>
                      <option value="Manager">Manager</option>
                    </select>
                    <input
                      type="text"
                      placeholder="Email or phone"
                      value={newMemberContact}
                      onChange={(e) => setNewMemberContact(e.target.value)}
                      className="h-9 px-2.5 rounded border border-[#E2E8E5] bg-white text-xs text-[#111827]"
                    />
                  </div>
                  <div className="flex items-center gap-2 pt-1">
                    <button
                      type="submit"
                      className="h-8 px-3 rounded bg-[#16A34A] text-white text-xs font-semibold cursor-pointer"
                    >
                      Add Member
                    </button>
                    <button
                      type="button"
                      onClick={() => setShowAddMember(false)}
                      className="h-8 px-2.5 text-xs text-[#64748B] hover:text-[#111827] cursor-pointer"
                    >
                      Cancel
                    </button>
                  </div>
                </form>
              ) : (
                <button
                  type="button"
                  onClick={() => setShowAddMember(true)}
                  className="w-full flex items-center justify-center gap-1.5 py-2 text-xs font-semibold text-[#16A34A] hover:bg-[#16A34A]/5 rounded-lg border border-dashed border-[#16A34A]/40 transition-colors cursor-pointer"
                >
                  <Plus className="w-3.5 h-3.5" />
                  <span>+ Add trainer or staff</span>
                </button>
              )}

              <div className="flex items-center gap-3 mt-2">
                <button
                  type="button"
                  onClick={() => setStep(4)}
                  className="flex-1 inline-flex items-center justify-center gap-2 h-11 rounded-lg border border-[#E2E8E5] bg-white hover:bg-zinc-50 text-[#64748B] text-sm font-semibold transition-all cursor-pointer"
                >
                  <ArrowLeft className="h-4 w-4" />
                  <span>Back</span>
                </button>
                <button
                  type="button"
                  onClick={() => setStep(6)}
                  className="flex-1 inline-flex items-center justify-center gap-2 h-11 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-sm font-semibold transition-all shadow-xs cursor-pointer"
                >
                  <span>Review & Verify</span>
                  <ArrowRight className="h-4 w-4" />
                </button>
              </div>
            </SpotlightCard>

            <div className="text-center">
              <button
                type="button"
                onClick={() => setStep(6)}
                className="text-sm text-[#64748B] hover:text-[#111827] transition-colors cursor-pointer"
              >
                Skip for now
              </button>
            </div>
          </motion.div>
        )}

        {/* ======================================================== */}
        {/* STEP 6: OWNER REVIEW & OTP VERIFICATION (LAST STEP!) */}
        {/* ======================================================== */}
        {step === 6 && (
          <motion.div
            key="step-6"
            initial={{ opacity: 0, y: 14, filter: "blur(4px)" }}
            animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
            exit={{ opacity: 0, y: -14, filter: "blur(4px)" }}
            transition={{ duration: 0.25, ease: "easeOut" }}
            className="w-full max-w-[420px] sm:max-w-[460px] mx-auto space-y-6"
          >
            <div className="text-center space-y-1.5">
              <p className="text-xs font-semibold text-[#16A34A] uppercase tracking-wider">
                Step 5 of 5 · Final Verification
              </p>
              <h1 className="text-2xl sm:text-[28px] font-bold text-[#111827] tracking-tight">
                Review & Verify Account
              </h1>
              <p className="text-sm text-[#64748B]">
                Confirm your owner details and enter the verification code.
              </p>
            </div>

            <SpotlightCard
              spotlightColor="rgba(22, 163, 74, 0.08)"
              className="bg-white rounded-2xl border border-[#E2E8E5] p-6 sm:p-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)] space-y-5"
            >
              {/* Owner Form Summary Card */}
              <div className="p-4 rounded-xl bg-[#F8FAFC] border border-[#E2E8E5] space-y-3">
                <div className="flex items-center justify-between border-b border-[#E2E8E5] pb-2.5">
                  <span className="text-xs font-bold text-[#111827] uppercase tracking-wider">Owner Profile</span>
                  <button
                    type="button"
                    onClick={() => setStep(2)}
                    className="text-xs text-[#16A34A] font-semibold hover:underline"
                  >
                    Edit Form
                  </button>
                </div>
                
                <div className="grid grid-cols-2 gap-3 text-xs">
                  <div>
                    <span className="text-[#64748B] block">Owner Name:</span>
                    <span className="font-semibold text-[#111827]">{fullName || "Not provided"}</span>
                  </div>
                  <div>
                    <span className="text-[#64748B] block">Work Email:</span>
                    <span className="font-semibold text-[#111827]">{email || "Not provided"}</span>
                  </div>
                  <div>
                    <span className="text-[#64748B] block">Gym / Business:</span>
                    <span className="font-semibold text-[#111827]">{gymName || "FitZone"}</span>
                  </div>
                  <div>
                    <span className="text-[#64748B] block">Contact Phone:</span>
                    <span className="font-semibold text-[#111827]">{gymPhone || "Not provided"}</span>
                  </div>
                  {gymCity && (
                    <div>
                      <span className="text-[#64748B] block">City:</span>
                      <span className="font-semibold text-[#111827]">{gymCity}</span>
                    </div>
                  )}
                  <div>
                    <span className="text-[#64748B] block">Scale:</span>
                    <span className="font-semibold text-[#111827]">{locationsCount}</span>
                  </div>
                </div>
              </div>

              {/* OTP section or Send OTP Trigger */}
              {!otpSent ? (
                <div className="space-y-4 pt-1">
                  {otpError && (
                    <div className="p-3.5 rounded-xl bg-rose-50 border border-rose-200 text-rose-700 text-xs flex flex-col gap-2">
                      <div className="flex items-start gap-2">
                        <AlertCircle className="w-4 h-4 text-rose-600 shrink-0 mt-0.5" />
                        <span className="font-medium">{otpError}</span>
                      </div>
                      {otpError.toLowerCase().includes("already") && (
                        <div className="flex items-center gap-2 pt-1 border-t border-rose-200/60">
                          <Link
                            href="/login"
                            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-rose-600 text-white font-semibold text-xs hover:bg-rose-700 transition"
                          >
                            Sign In to Existing Account
                          </Link>
                          <button
                            type="button"
                            onClick={() => {
                              setOtpError("");
                              setStep(1);
                            }}
                            className="px-2.5 py-1.5 rounded-lg border border-rose-300 text-rose-700 font-semibold text-xs hover:bg-rose-100 transition"
                          >
                            Change Email
                          </button>
                        </div>
                      )}
                    </div>
                  )}

                  <div className="p-3.5 rounded-xl border border-emerald-500/20 bg-emerald-500/5 text-xs text-[#111827] flex items-start gap-2.5">
                    <ShieldCheck className="w-5 h-5 text-[#16A34A] shrink-0 mt-0.5" />
                    <div>
                      <p className="font-semibold">Email Confirmation Required</p>
                      <p className="text-[#64748B] mt-0.5">
                        We will send a 6-digit OTP to <strong className="font-mono text-[#111827]">{email}</strong>.
                      </p>
                    </div>
                  </div>

                  <button
                    type="button"
                    onClick={() => setShowConfirmModal(true)}
                    disabled={isSendingOtp}
                    className="w-full inline-flex items-center justify-center gap-2 h-11 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-sm font-semibold transition-all shadow-xs cursor-pointer disabled:opacity-50"
                  >
                    {isSendingOtp ? (
                      <span className="h-5 w-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    ) : (
                      <>
                        <Mail className="h-4 w-4" />
                        <span>Send Verification OTP</span>
                      </>
                    )}
                  </button>
                </div>
              ) : (
                <div className="space-y-5 pt-1">
                  <div className="text-center space-y-1">
                    <p className="text-xs text-[#64748B]">Enter the 6-digit verification code sent to</p>
                    <p className="text-xs font-semibold font-mono text-[#111827]">{maskEmail(email)}</p>
                  </div>

                  {otpError && (
                    <div className="p-3 rounded-lg bg-rose-50 border border-rose-200 text-rose-700 text-xs text-center font-medium">
                      {otpError}
                    </div>
                  )}

                  {/* 6 Digit Inputs */}
                  <div className="flex justify-center gap-2 sm:gap-2.5">
                    {otpDigits.map((digit, idx) => (
                      <input
                        key={idx}
                        ref={(el) => {
                          otpInputsRef.current[idx] = el;
                        }}
                        type="text"
                        inputMode="numeric"
                        maxLength={1}
                        value={digit}
                        onChange={(e) => handleOtpChange(idx, e.target.value)}
                        onKeyDown={(e) => handleOtpKeyDown(idx, e)}
                        onPaste={handleOtpPaste}
                        className="w-11 h-12 sm:w-12 sm:h-12 rounded-lg border border-[#E2E8E5] bg-white text-center text-lg font-bold text-[#111827] focus:outline-none focus:border-[#16A34A] focus:ring-2 focus:ring-[#16A34A]/20 transition-all shadow-2xs"
                        autoFocus={idx === 0}
                      />
                    ))}
                  </div>

                  <div className="text-center text-xs text-[#64748B]">
                    {resendTimer > 0 ? (
                      <span>
                        Resend code in <strong className="text-[#111827]">{resendTimer}s</strong>
                      </span>
                    ) : (
                      <button
                        type="button"
                        onClick={handleResendOtp}
                        disabled={isSendingOtp}
                        className="font-semibold text-[#16A34A] hover:underline cursor-pointer"
                      >
                        Resend verification code
                      </button>
                    )}
                  </div>

                  <button
                    type="button"
                    onClick={() => triggerVerifyOtp()}
                    disabled={isVerifyingOtp}
                    className="w-full inline-flex items-center justify-center gap-2 h-11 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-sm font-semibold transition-all shadow-xs cursor-pointer"
                  >
                    {isVerifyingOtp ? (
                      <span className="h-5 w-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    ) : (
                      <>
                        <span>Verify & Launch Workspace</span>
                        <ArrowRight className="h-4 w-4" />
                      </>
                    )}
                  </button>
                </div>
              )}

              <div className="flex items-center gap-3 mt-2 border-t border-[#E2E8E5] pt-3">
                <button
                  type="button"
                  onClick={() => setStep(5)}
                  className="w-full inline-flex items-center justify-center gap-2 h-10 rounded-lg border border-[#E2E8E5] bg-white hover:bg-zinc-50 text-[#64748B] text-xs font-semibold transition-all cursor-pointer"
                >
                  <ArrowLeft className="h-3.5 w-3.5" />
                  <span>Back to Team Setup</span>
                </button>
              </div>
            </SpotlightCard>
          </motion.div>
        )}

        {/* ======================================================== */}
        {/* STEP 7: PLAN SELECTION & LAUNCH (TRIAL OR PAID PLAN) */}
        {/* ======================================================== */}
        {step === 7 && (
          <motion.div
            key="step-7"
            initial={{ opacity: 0, scale: 0.95, filter: "blur(4px)" }}
            animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
            exit={{ opacity: 0, scale: 0.95, filter: "blur(4px)" }}
            transition={{ duration: 0.3, ease: "easeOut" }}
            className="w-full max-w-[440px] sm:max-w-[540px] mx-auto space-y-5"
          >
            <div className="text-center space-y-1.5">
              <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full bg-emerald-50 border border-emerald-200 text-xs font-semibold text-[#16A34A]">
                <CheckCircle2 className="w-3.5 h-3.5" />
                Email Verified Successfully
              </span>
              <h1 className="text-2xl sm:text-[28px] font-bold text-[#111827] tracking-tight">
                Choose your starting plan
              </h1>
              <p className="text-xs sm:text-sm text-[#64748B]">
                Start with a 14-day Growth trial or select a subscription to proceed immediately.
              </p>
            </div>

            <SpotlightCard
              spotlightColor="rgba(22, 163, 74, 0.12)"
              className="relative overflow-hidden bg-white rounded-2xl border border-[#E2E8E5] p-5 sm:p-7 shadow-[0_8px_30px_rgba(0,0,0,0.04)] space-y-5"
            >
              <BorderBeam size={220} duration={7} colorFrom="#16A34A" colorTo="#34D399" />

              {/* Mode Selector Tabs: 14-Day Trial vs Paid Plans */}
              <div className="grid grid-cols-2 gap-2 p-1 bg-[#F1F5F9] rounded-xl border border-[#E2E8E5]">
                <button
                  type="button"
                  onClick={() => setChosenPlanType("trial")}
                  className={`py-2 px-3 rounded-lg text-xs font-bold transition-all flex items-center justify-center gap-1.5 cursor-pointer ${
                    chosenPlanType === "trial"
                      ? "bg-white text-[#16A34A] shadow-xs"
                      : "text-[#64748B] hover:text-[#111827]"
                  }`}
                >
                  <Sparkles className="w-3.5 h-3.5" />
                  <span>14-Day Free Trial</span>
                </button>
                <button
                  type="button"
                  onClick={() => setChosenPlanType("paid")}
                  className={`py-2 px-3 rounded-lg text-xs font-bold transition-all flex items-center justify-center gap-1.5 cursor-pointer ${
                    chosenPlanType === "paid"
                      ? "bg-white text-[#16A34A] shadow-xs"
                      : "text-[#64748B] hover:text-[#111827]"
                  }`}
                >
                  <span>Select Paid Plan</span>
                </button>
              </div>

              {/* OPTION A: 14-DAY FREE TRIAL (GROWTH FEATURES) */}
              {chosenPlanType === "trial" && (
                <div className="space-y-4">
                  <div className="p-4 bg-emerald-50/80 rounded-xl border border-emerald-200/90 text-left text-xs space-y-3">
                    <div className="flex items-center justify-between pb-2.5 border-b border-emerald-200/60">
                      <div>
                        <span className="font-bold text-sm text-[#15803D] block">Growth Tier Access</span>
                        <span className="text-[11px] text-[#166534]">14 Calendar Days · No Credit Card Required</span>
                      </div>
                      <span className="px-2.5 py-0.5 rounded font-bold text-[10px] bg-emerald-600 text-white tracking-wider">
                        FREE TRIAL
                      </span>
                    </div>

                    <div className="grid grid-cols-2 gap-2 text-[11px] text-[#334155]">
                      <div className="flex items-center gap-1.5">
                        <Check className="w-3.5 h-3.5 text-[#16A34A] shrink-0" />
                        <span>Up to <strong>35 Members</strong></span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <Check className="w-3.5 h-3.5 text-[#16A34A] shrink-0" />
                        <span>Trainer Accounts</span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <Check className="w-3.5 h-3.5 text-[#16A34A] shrink-0" />
                        <span>Attendance Reports & QR</span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <Check className="w-3.5 h-3.5 text-[#16A34A] shrink-0" />
                        <span>Workout Schedules</span>
                      </div>
                    </div>

                    <div className="pt-2 border-t border-emerald-200/50 flex items-center justify-between text-[11px] text-emerald-800">
                      <span>Workspace URL: <strong className="font-mono text-[#111827]">{effectiveSlug}.repsi.app</strong></span>
                      <span className="text-[10px] font-semibold text-[#15803D]">Zero auto-charge</span>
                    </div>
                  </div>

                  <div className="p-3 bg-[#F8FAFC] rounded-lg border border-[#E2E8E5] text-[11px] text-[#64748B] space-y-1">
                    <p className="text-[#111827] font-semibold">✓ Zero Risk Commitment</p>
                    <p>At trial end, choose any plan. Your member, attendance, and workout data is 100% preserved.</p>
                  </div>
                </div>
              )}

              {/* OPTION B: SELECT PAID PLAN */}
              {chosenPlanType === "paid" && (
                <div className="space-y-3.5">
                  {/* Monthly vs Annual Toggle */}
                  <div className="flex items-center justify-between px-1">
                    <span className="text-xs font-semibold text-[#111827]">Billing cycle:</span>
                    <div className="inline-flex p-0.5 rounded-lg bg-[#F1F5F9] border border-[#E2E8E5] text-xs">
                      <button
                        type="button"
                        onClick={() => setChosenBillingCycle("monthly")}
                        className={`px-2.5 py-1 rounded-md text-[11px] font-bold transition cursor-pointer ${
                          chosenBillingCycle === "monthly"
                            ? "bg-white text-[#111827] shadow-2xs"
                            : "text-[#64748B]"
                        }`}
                      >
                        Monthly
                      </button>
                      <button
                        type="button"
                        onClick={() => setChosenBillingCycle("annual")}
                        className={`px-2.5 py-1 rounded-md text-[11px] font-bold transition cursor-pointer flex items-center gap-1 ${
                          chosenBillingCycle === "annual"
                            ? "bg-[#16A34A] text-white shadow-2xs"
                            : "text-[#64748B]"
                        }`}
                      >
                        <span>Annual</span>
                        <span className="text-[9px] px-1 py-0.2 rounded bg-white/20 text-white font-extrabold">SAVE</span>
                      </button>
                    </div>
                  </div>

                  {/* 6 Paid Plans Catalog */}
                  <div className="space-y-2 max-h-[300px] overflow-y-auto pr-1">
                    {[
                      {
                        code: "basic",
                        name: "Basic",
                        monthlyPrice: "₹149/mo",
                        annualPrice: "₹129/mo",
                        members: "10 Members",
                        desc: "Member records, QR attendance & basic workouts",
                        badge: null,
                      },
                      {
                        code: "growth",
                        name: "Growth",
                        monthlyPrice: "₹499/mo",
                        annualPrice: "₹469/mo",
                        members: "35 Members",
                        desc: "Trainer accounts, attendance reports & structured workouts",
                        badge: "MOST POPULAR",
                      },
                      {
                        code: "premium",
                        name: "Premium",
                        monthlyPrice: "₹1,299/mo",
                        annualPrice: "₹1,099/mo",
                        members: "100 Members",
                        desc: "Diet plans, personalized workouts & progress tracking",
                        badge: "BEST VALUE",
                      },
                      {
                        code: "pro",
                        name: "Pro",
                        monthlyPrice: "₹2,499/mo",
                        annualPrice: "₹2,149/mo",
                        members: "250 Members",
                        desc: "Revenue reports, data exports & workout templates",
                        badge: null,
                      },
                      {
                        code: "pro_plus",
                        name: "Pro Plus+",
                        monthlyPrice: "₹4,999/mo",
                        annualPrice: "₹4,599/mo",
                        members: "Unlimited",
                        desc: "Unlimited members, bulk operations & priority SLA",
                        badge: "UNLIMITED",
                      },
                      {
                        code: "enterprise",
                        name: "Enterprise",
                        monthlyPrice: "Contact Sales",
                        annualPrice: "Contact Sales",
                        members: "Custom",
                        desc: "Multi-branch consolidated reporting, custom API",
                        badge: "CUSTOM",
                      },
                    ].map((p) => {
                      const isSelected = selectedPaidPlanCode === p.code;
                      const price = chosenBillingCycle === "annual" ? p.annualPrice : p.monthlyPrice;
                      return (
                        <div
                          key={p.code}
                          onClick={() => setSelectedPaidPlanCode(p.code)}
                          className={`p-3 rounded-xl border transition-all cursor-pointer flex items-center justify-between text-left ${
                            isSelected
                              ? "border-[#16A34A] bg-[#16A34A]/5 ring-2 ring-[#16A34A]/20"
                              : "border-[#E2E8E5] bg-white hover:border-[#16A34A]/50"
                          }`}
                        >
                          <div className="space-y-0.5">
                            <div className="flex items-center gap-2">
                              <span className="font-bold text-xs text-[#111827]">{p.name}</span>
                              <span className="text-[10px] font-semibold text-[#16A34A] bg-[#16A34A]/10 px-1.5 py-0.2 rounded">
                                {p.members}
                              </span>
                              {p.badge && (
                                <span className="text-[9px] font-bold text-white bg-[#111827] px-1.5 py-0.2 rounded">
                                  {p.badge}
                                </span>
                              )}
                            </div>
                            <p className="text-[11px] text-[#64748B]">{p.desc}</p>
                          </div>

                          <div className="text-right shrink-0 ml-3">
                            <span className="font-bold text-xs text-[#111827] block">{price}</span>
                            <div className="flex items-center justify-end mt-1">
                              <div className={`w-4 h-4 rounded-full border flex items-center justify-center ${
                                isSelected ? "border-[#16A34A] bg-[#16A34A]" : "border-[#CBD5E1]"
                              }`}>
                                {isSelected && <Check className="w-2.5 h-2.5 text-white stroke-[3]" />}
                              </div>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}

              {/* Action Button */}
              <button
                type="button"
                onClick={handleFinishLaunch}
                disabled={loading}
                className="w-full inline-flex items-center justify-center gap-2 h-11 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-sm font-semibold transition-all shadow-xs cursor-pointer disabled:opacity-50"
              >
                {loading ? (
                  <span className="h-5 w-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : chosenPlanType === "trial" ? (
                  <>
                    <span>Start 14-Day Free Trial & Enter Dashboard</span>
                    <ArrowRight className="h-4 w-4" />
                  </>
                ) : (
                  <>
                    <span>Proceed with {selectedPaidPlanCode === "enterprise" ? "Enterprise" : selectedPaidPlanCode.toUpperCase()} Plan</span>
                    <ArrowRight className="h-4 w-4" />
                  </>
                )}
              </button>
            </SpotlightCard>
          </motion.div>
        )}
        </AnimatePresence>
      </main>

      {/* Confirmation Modal Before Sending OTP */}
      <AnimatePresence>
        {showConfirmModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-xs"
          >
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: 8 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: 8 }}
              transition={{ duration: 0.2 }}
              className="bg-white rounded-2xl border border-[#E2E8E5] p-6 max-w-md w-full shadow-2xl space-y-5"
            >
              <div className="flex items-center justify-between border-b border-[#E2E8E5] pb-3">
                <div className="flex items-center gap-2 text-[#16A34A]">
                  <ShieldCheck className="w-5 h-5" />
                  <h3 className="font-bold text-base text-[#111827]">Confirm Email Address</h3>
                </div>
                <button
                  type="button"
                  onClick={() => setShowConfirmModal(false)}
                  className="text-[#94A3B8] hover:text-[#111827] transition-colors p-1"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="space-y-3 text-sm text-[#64748B]">
                <p>
                  We will dispatch a 6-digit verification code to the following work email address:
                </p>
                <div className="p-3 bg-[#F8FAFC] rounded-lg border border-[#E2E8E5] font-mono text-[#111827] font-semibold text-center text-base">
                  {email || "you@gym.com"}
                </div>
                <p className="text-xs text-[#64748B]">
                  Please confirm this email is correct before requesting the verification code.
                </p>
              </div>

              <div className="flex items-center gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => {
                    setShowConfirmModal(false);
                    setStep(1);
                  }}
                  className="flex-1 h-10 rounded-lg border border-[#E2E8E5] bg-white text-[#64748B] hover:text-[#111827] text-xs font-semibold transition-colors cursor-pointer"
                >
                  Edit Email
                </button>
                <button
                  type="button"
                  onClick={handleConfirmAndSendOtp}
                  className="flex-1 h-10 rounded-lg bg-[#16A34A] hover:bg-[#15803D] text-white text-xs font-semibold transition-colors cursor-pointer"
                >
                  Confirm & Send OTP
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Minimal Footer */}
      <footer className="py-6 text-center text-xs text-[#94A3B8]">
        <p>
          © 2026 REPSI ·{" "}
          <Link href="/about" className="hover:text-[#111827] transition-colors">
            Privacy
          </Link>{" "}
          ·{" "}
          <Link href="/about" className="hover:text-[#111827] transition-colors">
            Terms
          </Link>
        </p>
      </footer>
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import {
  CreditCard,
  TrendingUp,
  CheckCircle2,
  AlertTriangle,
  Search,
  RefreshCw,
  Plus,
  Clock,
  Sparkles,
  ShieldCheck,
  Building2,
  Calendar,
  Lock,
  Unlock,
  Sliders,
  Gift,
  History,
  X,
  ChevronRight,
  ExternalLink,
  Edit2,
  User,
  Users
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { repsiApi } from "@/lib/api";
import { motion, AnimatePresence } from "framer-motion";
import { SpotlightCard } from "@/components/ui/spotlight-card";
import { ShinyText } from "@/components/ui/shiny-text";
import { AnimatedNumber } from "@/components/ui/animated-number";

export default function SuperAdminSubscriptionsPage() {
  const [activeTab, setActiveTab] = useState<"gyms" | "plans">("gyms");
  const [loading, setLoading] = useState(true);

  // Gyms state
  const [gyms, setGyms] = useState<any[]>([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [planFilter, setPlanFilter] = useState("all");
  const [filterType, setFilterType] = useState("all");
  const [trialAnalytics, setTrialAnalytics] = useState<any | null>(null);
  const [reconciling, setReconciling] = useState(false);

  // Plans catalog state
  const [plans, setPlans] = useState<any[]>([]);

  // Modals state
  const [selectedGym, setSelectedGym] = useState<any | null>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const [modalType, setModalType] = useState<
    "extend_trial" | "change_plan" | "complimentary" | "override" | "status" | "history" | "edit_plan" | null
  >(null);

  // Extend trial form
  const [trialDays, setTrialDays] = useState(14);
  const [actionReason, setActionReason] = useState("");

  // Change plan form
  const [targetPlanCode, setTargetPlanCode] = useState("growth");
  const [targetBillingCycle, setTargetBillingCycle] = useState("monthly");

  // Complimentary form
  const [compDays, setCompDays] = useState(30);
  const [compPermanent, setCompPermanent] = useState(false);

  // Overrides form
  const [customMemberLimit, setCustomMemberLimit] = useState<number | string>("");
  const [customTrainerLimit, setCustomTrainerLimit] = useState<number | string>("");
  const [customStaffLimit, setCustomStaffLimit] = useState<number | string>("");

  // Plan editor form
  const [editingPlan, setEditingPlan] = useState<any | null>(null);

  // Status toggle form
  const [statusAction, setStatusAction] = useState<"suspended" | "active">("suspended");

  // Detailed Gym data for History/Detail modal
  const [detailedGymSub, setDetailedGymSub] = useState<any | null>(null);

  const loadData = async () => {
    setLoading(true);
    try {
      const [gymsData, plansData, analyticsData] = await Promise.all([
        repsiApi.getSuperAdminGymSubscriptions({
          q: searchQuery,
          status: statusFilter,
          plan: planFilter,
          filter_type: filterType,
        }),
        repsiApi.getSuperAdminSubscriptionPlans(),
        repsiApi.getSuperAdminTrialAnalytics().catch(() => null),
      ]);
      setGyms(gymsData || []);
      setPlans(plansData || []);
      setTrialAnalytics(analyticsData);
    } catch (err) {
      console.error("Failed to load subscription data", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [statusFilter, planFilter, filterType]);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    loadData();
  };

  const handleReconcileTrials = async () => {
    setReconciling(true);
    try {
      const res = await repsiApi.reconcileTrials();
      const expCount = res?.reconciliation?.expired_count ?? 0;
      const remCount = res?.reminders?.reminders_sent ?? 0;
      alert(`Lifecycle sync complete:\n• ${expCount} expired trials updated\n• ${remCount} milestone reminders delivered`);
      await loadData();
    } catch (err: any) {
      alert(err.message || "Failed to reconcile trials");
    } finally {
      setReconciling(false);
    }
  };

  const openExtendTrial = (gym: any) => {
    setSelectedGym(gym);
    setTrialDays(14);
    setActionReason("Owner requested onboarding extension");
    setModalType("extend_trial");
  };

  const handleExtendTrialSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedGym) return;
    setActionLoading(true);
    try {
      await repsiApi.extendSuperAdminGymTrial(selectedGym.workspace_id, trialDays, actionReason);
      alert(`Extended trial by ${trialDays} days for ${selectedGym.workspace_name}.`);
      setModalType(null);
      await loadData();
    } catch (err: any) {
      alert(err.message || "Failed to extend trial");
    } finally {
      setActionLoading(false);
    }
  };

  const openChangePlan = (gym: any) => {
    setSelectedGym(gym);
    setTargetPlanCode(gym.plan_code || "growth");
    setTargetBillingCycle(gym.billing_cycle || "monthly");
    setActionReason("Super Admin plan migration");
    setModalType("change_plan");
  };

  const handleChangePlanSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedGym) return;
    setActionLoading(true);
    try {
      await repsiApi.changeSuperAdminGymPlan(selectedGym.workspace_id, {
        plan_code: targetPlanCode,
        billing_cycle: targetBillingCycle,
        reason: actionReason,
      });
      alert(`Updated plan to ${targetPlanCode.toUpperCase()} for ${selectedGym.workspace_name}.`);
      setModalType(null);
      await loadData();
    } catch (err: any) {
      alert(err.message || "Failed to change plan");
    } finally {
      setActionLoading(false);
    }
  };

  const openComplimentary = (gym: any) => {
    setSelectedGym(gym);
    setCompDays(30);
    setCompPermanent(false);
    setActionReason("Promotional partner grant");
    setModalType("complimentary");
  };

  const handleComplimentarySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedGym) return;
    setActionLoading(true);
    try {
      await repsiApi.grantSuperAdminComplimentary(selectedGym.workspace_id, {
        days: compPermanent ? undefined : compDays,
        is_permanent: compPermanent,
        reason: actionReason,
      });
      alert(`Complimentary access granted for ${selectedGym.workspace_name}.`);
      setModalType(null);
      await loadData();
    } catch (err: any) {
      alert(err.message || "Failed to grant complimentary access");
    } finally {
      setActionLoading(false);
    }
  };

  const openOverrides = (gym: any) => {
    setSelectedGym(gym);
    setCustomMemberLimit(gym.member_limit === -1 ? "" : gym.member_limit);
    setCustomTrainerLimit(gym.trainer_limit === -1 ? "" : gym.trainer_limit);
    setCustomStaffLimit("");
    setActionReason("Custom gym capacity upgrade");
    setModalType("override");
  };

  const handleOverridesSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedGym) return;
    setActionLoading(true);
    try {
      await repsiApi.setSuperAdminGymOverride(selectedGym.workspace_id, {
        custom_member_limit: customMemberLimit === "" ? null : Number(customMemberLimit),
        custom_trainer_limit: customTrainerLimit === "" ? null : Number(customTrainerLimit),
        custom_staff_limit: customStaffLimit === "" ? null : Number(customStaffLimit),
        reason: actionReason,
      });
      alert(`Overrides saved for ${selectedGym.workspace_name}.`);
      setModalType(null);
      await loadData();
    } catch (err: any) {
      alert(err.message || "Failed to save overrides");
    } finally {
      setActionLoading(false);
    }
  };

  const openStatusToggle = (gym: any, target: "suspended" | "active") => {
    setSelectedGym(gym);
    setStatusAction(target);
    setActionReason(target === "suspended" ? "Terms of service audit / Non-payment" : "Account reinstated");
    setModalType("status");
  };

  const handleStatusSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedGym) return;
    setActionLoading(true);
    try {
      await repsiApi.updateSuperAdminGymSubscriptionStatus(selectedGym.workspace_id, {
        status: statusAction,
        reason: actionReason,
      });
      alert(`Subscription marked as ${statusAction.toUpperCase()} for ${selectedGym.workspace_name}.`);
      setModalType(null);
      await loadData();
    } catch (err: any) {
      alert(err.message || "Failed to update status");
    } finally {
      setActionLoading(false);
    }
  };

  const openHistory = async (gym: any) => {
    setSelectedGym(gym);
    setModalType("history");
    try {
      const details = await repsiApi.getSuperAdminGymSubscription(gym.workspace_id);
      setDetailedGymSub(details);
    } catch (err) {
      console.error(err);
    }
  };

  const openEditPlan = (plan: any) => {
    setEditingPlan({ ...plan });
    setModalType("edit_plan");
  };

  const handleEditPlanSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingPlan) return;
    setActionLoading(true);
    try {
      await repsiApi.updateSuperAdminSubscriptionPlan(editingPlan.id, {
        name: editingPlan.name,
        monthly_price: Number(editingPlan.monthly_price),
        annual_price: Number(editingPlan.annual_price),
        member_limit: Number(editingPlan.member_limit),
        trainer_limit: Number(editingPlan.trainer_limit),
        staff_limit: Number(editingPlan.staff_limit),
        is_active: editingPlan.is_active,
      });
      alert(`Plan ${editingPlan.name} updated successfully.`);
      setModalType(null);
      await loadData();
    } catch (err: any) {
      alert(err.message || "Failed to update plan");
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-white tracking-tight flex items-center gap-2.5">
            <CreditCard className="w-6 h-6 text-emerald-400" />
            SaaS Subscription & Entitlement Control
          </h1>
          <p className="text-xs text-zinc-400 mt-1">
            Super Admin control center: manage gym plan allocations, 14-day trials, feature gates, and audit trails.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={loadData}
            disabled={loading}
            className="border-zinc-800 bg-zinc-900/80 text-zinc-300 hover:text-white text-xs gap-1.5"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin" : ""}`} />
            Refresh
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-zinc-800 gap-4">
        <button
          onClick={() => setActiveTab("gyms")}
          className={`pb-3 text-sm font-semibold transition-colors flex items-center gap-2 relative ${
            activeTab === "gyms" ? "text-emerald-400" : "text-zinc-400 hover:text-zinc-200"
          }`}
        >
          <Building2 className="w-4 h-4" />
          Gym Tenant Subscriptions ({gyms.length})
          {activeTab === "gyms" && (
            <motion.div
              layoutId="superAdminSubTabIndicator"
              className="absolute bottom-0 left-0 right-0 h-0.5 bg-emerald-500 shadow-sm shadow-emerald-500/50"
              transition={{ type: "spring", stiffness: 400, damping: 30 }}
            />
          )}
        </button>

        <button
          onClick={() => setActiveTab("plans")}
          className={`pb-3 text-sm font-semibold transition-colors flex items-center gap-2 relative ${
            activeTab === "plans" ? "text-emerald-400" : "text-zinc-400 hover:text-zinc-200"
          }`}
        >
          <Sliders className="w-4 h-4" />
          Catalog Plans & Entitlements ({plans.length})
          {activeTab === "plans" && (
            <motion.div
              layoutId="superAdminSubTabIndicator"
              className="absolute bottom-0 left-0 right-0 h-0.5 bg-emerald-500 shadow-sm shadow-emerald-500/50"
              transition={{ type: "spring", stiffness: 400, damping: 30 }}
            />
          )}
        </button>
      </div>

      {/* TAB 1: GYMS SUBSCRIPTIONS */}
      {activeTab === "gyms" && (
        <div className="space-y-6">
          {/* Super Admin 14-Day Trial & Subscription Overview Grid */}
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
            <div className="p-3.5 rounded-xl border border-zinc-800 bg-zinc-900/60 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-zinc-400">Total Gyms</span>
              <div className="text-xl font-black text-white mt-1">
                {trialAnalytics?.total_businesses ?? gyms.length}
              </div>
              <span className="text-[10px] text-zinc-500 mt-1">Registered businesses</span>
            </div>

            <div className="p-3.5 rounded-xl border border-emerald-500/30 bg-emerald-500/5 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-emerald-400 flex items-center gap-1">
                <Clock className="w-3 h-3" /> Active Trials
              </span>
              <div className="text-xl font-black text-emerald-400 mt-1">
                {trialAnalytics?.active_trials ?? 0}
              </div>
              <span className="text-[10px] text-emerald-500/70 mt-1">Growth plan (35 cap)</span>
            </div>

            <div className="p-3.5 rounded-xl border border-amber-500/30 bg-amber-500/5 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-amber-400 flex items-center gap-1">
                <AlertTriangle className="w-3 h-3" /> Expiring &le; 3d
              </span>
              <div className="text-xl font-black text-amber-400 mt-1">
                {trialAnalytics?.trials_expiring_3_days ?? 0}
              </div>
              <span className="text-[10px] text-amber-500/70 mt-1">
                {trialAnalytics?.trials_expiring_today ?? 0} expiring today
              </span>
            </div>

            <div className="p-3.5 rounded-xl border border-rose-500/30 bg-rose-500/5 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-rose-400 flex items-center gap-1">
                <Lock className="w-3 h-3" /> Expired Trials
              </span>
              <div className="text-xl font-black text-rose-400 mt-1">
                {trialAnalytics?.expired_trials ?? 0}
              </div>
              <span className="text-[10px] text-rose-500/70 mt-1">Requires upgrade</span>
            </div>

            <div className="p-3.5 rounded-xl border border-sky-500/30 bg-sky-500/5 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-sky-400 flex items-center gap-1">
                <CheckCircle2 className="w-3 h-3" /> Active Paid
              </span>
              <div className="text-xl font-black text-sky-400 mt-1">
                {trialAnalytics?.active_paid ?? 0}
              </div>
              <span className="text-[10px] text-sky-500/70 mt-1">Active subscriptions</span>
            </div>

            <div className="p-3.5 rounded-xl border border-purple-500/30 bg-purple-500/5 flex flex-col justify-between">
              <span className="text-[11px] font-medium text-purple-400 flex items-center gap-1">
                <TrendingUp className="w-3 h-3" /> Conversion Rate
              </span>
              <div className="text-xl font-black text-purple-400 mt-1">
                {trialAnalytics?.conversion_rate_pct ?? 0}%
              </div>
              <span className="text-[10px] text-purple-500/70 mt-1">Trial to paid conversions</span>
            </div>
          </div>

          {/* Quick Filter Tabs & Action Bar */}
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-1.5 p-1 rounded-xl bg-zinc-900 border border-zinc-800 text-xs">
              {[
                { id: "all", label: "All Businesses" },
                { id: "active_trial", label: "Active Trials" },
                { id: "expiring_soon", label: "Expiring Soon (&le; 3d)" },
                { id: "expired", label: "Expired Trials" },
                { id: "paid", label: "Active Paid" },
              ].map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setFilterType(tab.id)}
                  className={`px-3 py-1.5 rounded-lg font-medium transition-colors ${
                    filterType === tab.id
                      ? "bg-emerald-500/20 text-emerald-400 font-bold border border-emerald-500/30"
                      : "text-zinc-400 hover:text-white"
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            <Button
              size="sm"
              variant="outline"
              onClick={handleReconcileTrials}
              disabled={reconciling}
              className="border-zinc-800 bg-zinc-900/80 text-zinc-300 hover:text-white text-xs gap-1.5 cursor-pointer"
            >
              <RefreshCw className={`w-3.5 h-3.5 ${reconciling ? "animate-spin" : ""}`} />
              {reconciling ? "Syncing..." : "Sync Trial Lifecycle"}
            </Button>
          </div>

          {/* Search & Select Filter Bar */}
          <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-4 rounded-xl border border-zinc-800 bg-zinc-900/60">
            <form onSubmit={handleSearchSubmit} className="relative flex-1">
              <Search className="w-4 h-4 text-zinc-400 absolute left-3 top-1/2 -translate-y-1/2" />
              <Input
                placeholder="Search by gym name, workspace slug, or owner email..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-9 bg-zinc-950 border-zinc-800 text-xs text-white"
              />
            </form>

            <div className="flex items-center gap-2">
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="bg-zinc-950 border border-zinc-800 text-zinc-300 text-xs rounded-lg px-3 py-2 outline-none"
              >
                <option value="all">All Statuses</option>
                <option value="trialing">Trialing (Growth)</option>
                <option value="active">Active (Paid)</option>
                <option value="grace_period">Grace Period</option>
                <option value="expired">Expired</option>
                <option value="suspended">Suspended</option>
                <option value="cancelled">Cancelled</option>
              </select>

              <select
                value={planFilter}
                onChange={(e) => setPlanFilter(e.target.value)}
                className="bg-zinc-950 border border-zinc-800 text-zinc-300 text-xs rounded-lg px-3 py-2 outline-none"
              >
                <option value="all">All Plans</option>
                <option value="basic">Basic</option>
                <option value="growth">Growth</option>
                <option value="premium">Premium</option>
                <option value="pro">Pro</option>
                <option value="pro_plus">Pro Plus+</option>
                <option value="enterprise">Enterprise</option>
              </select>
            </div>
          </div>

          {/* Table */}
          <div className="rounded-xl border border-zinc-800 bg-zinc-900/40 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs text-zinc-300">
                <thead className="bg-zinc-900/90 text-[11px] font-semibold uppercase text-zinc-400 border-b border-zinc-800">
                  <tr>
                    <th className="py-3 px-4">Gym Tenant</th>
                    <th className="py-3 px-4">Owner</th>
                    <th className="py-3 px-4">Effective Plan</th>
                    <th className="py-3 px-4">Status</th>
                    <th className="py-3 px-4">Active Capacity</th>
                    <th className="py-3 px-4">Expiry Date</th>
                    <th className="py-3 px-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-zinc-800/60 font-medium">
                  {loading ? (
                    <tr>
                      <td colSpan={7} className="py-8 text-center text-zinc-500">
                        <RefreshCw className="w-5 h-5 animate-spin mx-auto mb-2 text-emerald-400" />
                        Loading gym subscriptions...
                      </td>
                    </tr>
                  ) : gyms.length === 0 ? (
                    <tr>
                      <td colSpan={7} className="py-8 text-center text-zinc-500">
                        No gym subscriptions found matching your filters.
                      </td>
                    </tr>
                  ) : (
                    gyms.map((gym) => {
                      const isUnlimited = gym.member_limit === -1;
                      const isSuspended = gym.status === "suspended";
                      const isTrial = gym.status === "trialing";
                      return (
                        <tr key={gym.subscription_id} className="hover:bg-zinc-800/30 transition-colors">
                          <td className="py-3 px-4">
                            <div className="font-bold text-white text-sm">{gym.workspace_name}</div>
                            <div className="text-[11px] text-zinc-400 font-mono">/{gym.workspace_slug}</div>
                          </td>

                          <td className="py-3 px-4">
                            <div className="text-zinc-200">{gym.owner_name || "—"}</div>
                            <div className="text-[11px] text-zinc-500">{gym.owner_email || "—"}</div>
                          </td>

                          <td className="py-3 px-4">
                            <div className="flex items-center gap-1.5 font-bold text-emerald-400 uppercase">
                              <Sparkles className="w-3.5 h-3.5" />
                              {gym.plan_name}
                            </div>
                            <div className="text-[10px] text-zinc-500">
                              {gym.billing_cycle || "monthly"} • ₹{gym.plan_price || 0}
                            </div>
                          </td>

                          <td className="py-3 px-4">
                            <span
                              className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${
                                gym.status === "active"
                                  ? "bg-emerald-500/20 text-emerald-400 border border-emerald-500/30"
                                  : gym.status === "trialing"
                                  ? "bg-amber-500/20 text-amber-300 border border-amber-500/30"
                                  : gym.status === "suspended"
                                  ? "bg-rose-500/20 text-rose-400 border border-rose-500/30"
                                  : "bg-zinc-800 text-zinc-400 border border-zinc-700"
                              }`}
                            >
                              {gym.status}
                            </span>
                            {gym.is_complimentary && (
                              <span className="block mt-1 text-[9px] text-purple-400 font-bold">
                                ★ COMPLIMENTARY
                              </span>
                            )}
                          </td>

                          <td className="py-3 px-4">
                            <div className="text-zinc-200">
                              Members: <strong className="text-white">{gym.active_members_count}</strong> /{" "}
                              {isUnlimited ? "Unlimited" : gym.member_limit}
                            </div>
                            <div className="text-[10px] text-zinc-500">
                              Trainers: {gym.active_trainers_count} / {gym.trainer_limit === -1 ? "Unlimited" : gym.trainer_limit}
                            </div>
                          </td>

                          <td className="py-3 px-4 font-mono text-[11px]">
                            {gym.expires_at ? new Date(gym.expires_at).toLocaleDateString() : "Permanent / None"}
                            {isTrial && gym.expires_at && (
                              <span className="block text-[10px] text-amber-400">
                                {Math.max(0, Math.ceil((new Date(gym.expires_at).getTime() - Date.now()) / (1000 * 3600 * 24)))} days left
                              </span>
                            )}
                          </td>

                          <td className="py-3 px-4 text-right">
                            <div className="flex items-center justify-end gap-1.5 flex-wrap">
                              {/* Extend Trial */}
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => openExtendTrial(gym)}
                                className="h-7 text-[10px] bg-zinc-900 border-zinc-700 text-amber-300 hover:bg-amber-500/10"
                                title="Extend Trial"
                              >
                                <Clock className="w-3 h-3 mr-1" />
                                +Trial
                              </Button>

                              {/* Change Plan */}
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => openChangePlan(gym)}
                                className="h-7 text-[10px] bg-zinc-900 border-zinc-700 text-zinc-300 hover:text-white"
                                title="Change Plan"
                              >
                                <Edit2 className="w-3 h-3 mr-1" />
                                Plan
                              </Button>

                              {/* Overrides */}
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => openOverrides(gym)}
                                className="h-7 text-[10px] bg-zinc-900 border-zinc-700 text-zinc-300 hover:text-white"
                                title="Set Resource Overrides"
                              >
                                <Sliders className="w-3 h-3" />
                              </Button>

                              {/* Complimentary */}
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => openComplimentary(gym)}
                                className="h-7 text-[10px] bg-zinc-900 border-zinc-700 text-purple-400 hover:bg-purple-500/10"
                                title="Grant Complimentary Access"
                              >
                                <Gift className="w-3 h-3" />
                              </Button>

                              {/* Suspend or Reactivate */}
                              {isSuspended ? (
                                <Button
                                  size="sm"
                                  onClick={() => openStatusToggle(gym, "active")}
                                  className="h-7 text-[10px] bg-emerald-600 hover:bg-emerald-700 text-white"
                                  title="Reactivate subscription"
                                >
                                  <Unlock className="w-3 h-3" />
                                </Button>
                              ) : (
                                <Button
                                  size="sm"
                                  variant="destructive"
                                  onClick={() => openStatusToggle(gym, "suspended")}
                                  className="h-7 text-[10px] bg-rose-600 hover:bg-rose-700 text-white"
                                  title="Suspend subscription"
                                >
                                  <Lock className="w-3 h-3" />
                                </Button>
                              )}

                              {/* History / Audit */}
                              <Button
                                size="sm"
                                variant="outline"
                                onClick={() => openHistory(gym)}
                                className="h-7 text-[10px] bg-zinc-900 border-zinc-700 text-zinc-400 hover:text-white"
                                title="Audit history"
                              >
                                <History className="w-3 h-3" />
                              </Button>
                            </div>
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* TAB 2: PLANS & ENTITLEMENTS CATALOG */}
      {activeTab === "plans" && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {plans.map((p) => (
              <SpotlightCard
                key={p.id}
                spotlightColor="rgba(16, 185, 129, 0.12)"
                className="p-5 rounded-2xl border border-zinc-800 bg-zinc-900/60 flex flex-col justify-between space-y-4"
              >
                <div>
                  <div className="flex items-center justify-between">
                    <span className="text-xs font-mono font-bold text-emerald-400 uppercase tracking-wider">
                      {p.code}
                    </span>
                    <span
                      className={`text-[10px] px-2 py-0.5 rounded font-semibold ${
                        p.is_active ? "bg-emerald-500/20 text-emerald-400" : "bg-zinc-800 text-zinc-500"
                      }`}
                    >
                      {p.is_active ? "ACTIVE CATALOG" : "INACTIVE"}
                    </span>
                  </div>

                  <h3 className="text-xl font-bold text-white mt-1">{p.name}</h3>

                  <div className="flex items-baseline gap-2 mt-2">
                    <span className="text-2xl font-black text-white">
                      {p.monthly_price === 0 ? "Custom" : `₹${p.monthly_price}`}
                    </span>
                    <span className="text-xs text-zinc-400">/ mo</span>
                    <span className="text-xs text-zinc-500 font-mono">
                      (Annual: ₹{p.annual_price || 0})
                    </span>
                  </div>

                  <div className="mt-4 pt-3 border-t border-zinc-800 text-xs space-y-1.5 text-zinc-300">
                    <div>
                      • Member Limit:{" "}
                      <strong className="text-white">
                        {p.member_limit === -1 ? "Unlimited" : p.member_limit}
                      </strong>
                    </div>
                    <div>
                      • Trainer Limit:{" "}
                      <strong className="text-white">
                        {p.trainer_limit === -1 ? "Unlimited" : p.trainer_limit}
                      </strong>
                    </div>
                    <div>
                      • Staff Limit:{" "}
                      <strong className="text-white">
                        {p.staff_limit === -1 ? "Unlimited" : p.staff_limit}
                      </strong>
                    </div>
                  </div>

                  <div className="mt-4 pt-3 border-t border-zinc-800 text-xs text-zinc-400 space-y-1">
                    <div className="text-[11px] font-semibold text-zinc-300">Features Unlocked:</div>
                    <div className="flex flex-wrap gap-1 mt-1">
                      {Object.keys(p.features || {}).map((f) => (
                        <span key={f} className="px-1.5 py-0.5 rounded bg-zinc-800 font-mono text-[9px] text-zinc-300">
                          {f}
                        </span>
                      ))}
                    </div>
                  </div>
                </div>

                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => openEditPlan(p)}
                  className="w-full bg-zinc-950 border-zinc-700 text-zinc-200 hover:text-white text-xs gap-1.5"
                >
                  <Edit2 className="w-3.5 h-3.5" />
                  Edit Plan Details & Limits
                </Button>
              </SpotlightCard>
            ))}
          </div>
        </div>
      )}

      {/* ======================================================== */}
      {/* ACTION MODALS */}
      {/* ======================================================== */}

      {/* EXTEND TRIAL MODAL */}
      {modalType === "extend_trial" && selectedGym && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <div className="bg-zinc-950 border border-zinc-800 rounded-2xl p-6 max-w-md w-full shadow-2xl space-y-4 text-white">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
              <h3 className="font-bold text-base flex items-center gap-2 text-amber-400">
                <Clock className="w-5 h-5" />
                Extend 14-Day Free Trial
              </h3>
              <button onClick={() => setModalType(null)} className="text-zinc-400 hover:text-white">
                <X className="w-4 h-4" />
              </button>
            </div>

            <p className="text-xs text-zinc-300">
              Extend access for <strong className="text-white">{selectedGym.workspace_name}</strong> without creating duplicate subscriptions.
            </p>

            <form onSubmit={handleExtendTrialSubmit} className="space-y-4 text-xs">
              <div>
                <label className="block text-zinc-400 mb-1">Additional Days</label>
                <div className="grid grid-cols-4 gap-2">
                  {[7, 14, 30, 60].map((d) => (
                    <button
                      key={d}
                      type="button"
                      onClick={() => setTrialDays(d)}
                      className={`py-2 rounded-lg font-bold border transition ${
                        trialDays === d
                          ? "bg-amber-500/20 border-amber-500 text-amber-300"
                          : "bg-zinc-900 border-zinc-800 text-zinc-400"
                      }`}
                    >
                      +{d} Days
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-zinc-400 mb-1">Reason for Extension</label>
                <Input
                  value={actionReason}
                  onChange={(e) => setActionReason(e.target.value)}
                  placeholder="e.g. Granted by CEO for pilot onboarding"
                  className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  required
                />
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <Button type="button" variant="outline" onClick={() => setModalType(null)} className="text-xs">
                  Cancel
                </Button>
                <Button type="submit" disabled={actionLoading} className="bg-amber-600 hover:bg-amber-700 text-white text-xs">
                  {actionLoading ? "Applying..." : "Confirm Extension"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* CHANGE PLAN MODAL */}
      {modalType === "change_plan" && selectedGym && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <div className="bg-zinc-950 border border-zinc-800 rounded-2xl p-6 max-w-md w-full shadow-2xl space-y-4 text-white">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
              <h3 className="font-bold text-base flex items-center gap-2 text-emerald-400">
                <Edit2 className="w-5 h-5" />
                Change Gym Plan
              </h3>
              <button onClick={() => setModalType(null)} className="text-zinc-400 hover:text-white">
                <X className="w-4 h-4" />
              </button>
            </div>

            <p className="text-xs text-zinc-300">
              Assign a new catalog plan to <strong className="text-white">{selectedGym.workspace_name}</strong>.
            </p>

            <form onSubmit={handleChangePlanSubmit} className="space-y-4 text-xs">
              <div>
                <label className="block text-zinc-400 mb-1">Target Plan</label>
                <select
                  value={targetPlanCode}
                  onChange={(e) => setTargetPlanCode(e.target.value)}
                  className="w-full bg-zinc-900 border border-zinc-800 rounded-lg p-2.5 text-xs text-white outline-none"
                >
                  <option value="basic">Basic (10 Members · ₹149/mo)</option>
                  <option value="growth">Growth (35 Members · ₹499/mo)</option>
                  <option value="premium">Premium (100 Members · ₹1,299/mo)</option>
                  <option value="pro">Pro (250 Members · ₹2,499/mo)</option>
                  <option value="pro_plus">Pro Plus+ (Unlimited Members · ₹4,999/mo)</option>
                  <option value="enterprise">Enterprise (Custom)</option>
                </select>
              </div>

              <div>
                <label className="block text-zinc-400 mb-1">Billing Cycle</label>
                <select
                  value={targetBillingCycle}
                  onChange={(e) => setTargetBillingCycle(e.target.value)}
                  className="w-full bg-zinc-900 border border-zinc-800 rounded-lg p-2.5 text-xs text-white outline-none"
                >
                  <option value="monthly">Monthly</option>
                  <option value="annual">Annual</option>
                </select>
              </div>

              <div>
                <label className="block text-zinc-400 mb-1">Administrative Reason</label>
                <Input
                  value={actionReason}
                  onChange={(e) => setActionReason(e.target.value)}
                  placeholder="e.g. Plan upgrade requested via support ticket"
                  className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  required
                />
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <Button type="button" variant="outline" onClick={() => setModalType(null)} className="text-xs">
                  Cancel
                </Button>
                <Button type="submit" disabled={actionLoading} className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs">
                  {actionLoading ? "Applying..." : "Assign Plan"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* COMPLIMENTARY ACCESS MODAL */}
      {modalType === "complimentary" && selectedGym && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <div className="bg-zinc-950 border border-zinc-800 rounded-2xl p-6 max-w-md w-full shadow-2xl space-y-4 text-white">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
              <h3 className="font-bold text-base flex items-center gap-2 text-purple-400">
                <Gift className="w-5 h-5" />
                Grant Complimentary Access
              </h3>
              <button onClick={() => setModalType(null)} className="text-zinc-400 hover:text-white">
                <X className="w-4 h-4" />
              </button>
            </div>

            <p className="text-xs text-zinc-300">
              Grant free complimentary access to <strong className="text-white">{selectedGym.workspace_name}</strong> without tampering billing ledger history.
            </p>

            <form onSubmit={handleComplimentarySubmit} className="space-y-4 text-xs">
              <div className="flex items-center gap-2 p-3 bg-zinc-900 rounded-xl border border-zinc-800">
                <input
                  type="checkbox"
                  id="compPerm"
                  checked={compPermanent}
                  onChange={(e) => setCompPermanent(e.target.checked)}
                  className="rounded border-zinc-700"
                />
                <label htmlFor="compPerm" className="text-xs font-semibold text-zinc-200">
                  Grant Permanent Complimentary Access (until manually revoked)
                </label>
              </div>

              {!compPermanent && (
                <div>
                  <label className="block text-zinc-400 mb-1">Duration (Days)</label>
                  <Input
                    type="number"
                    value={compDays}
                    onChange={(e) => setCompDays(Number(e.target.value))}
                    min={1}
                    className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  />
                </div>
              )}

              <div>
                <label className="block text-zinc-400 mb-1">Reason</label>
                <Input
                  value={actionReason}
                  onChange={(e) => setActionReason(e.target.value)}
                  placeholder="e.g. VIP Partner sponsorship"
                  className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  required
                />
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <Button type="button" variant="outline" onClick={() => setModalType(null)} className="text-xs">
                  Cancel
                </Button>
                <Button type="submit" disabled={actionLoading} className="bg-purple-600 hover:bg-purple-700 text-white text-xs">
                  {actionLoading ? "Granting..." : "Grant Access"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* OVERRIDES MODAL */}
      {modalType === "override" && selectedGym && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <div className="bg-zinc-950 border border-zinc-800 rounded-2xl p-6 max-w-md w-full shadow-2xl space-y-4 text-white">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
              <h3 className="font-bold text-base flex items-center gap-2 text-blue-400">
                <Sliders className="w-5 h-5" />
                Configure Tenant Resource Overrides
              </h3>
              <button onClick={() => setModalType(null)} className="text-zinc-400 hover:text-white">
                <X className="w-4 h-4" />
              </button>
            </div>

            <p className="text-xs text-zinc-300">
              Apply per-gym custom limits to <strong className="text-white">{selectedGym.workspace_name}</strong>. Leave empty to use plan defaults.
            </p>

            <form onSubmit={handleOverridesSubmit} className="space-y-4 text-xs">
              <div className="grid grid-cols-3 gap-3">
                <div>
                  <label className="block text-zinc-400 mb-1">Member Limit</label>
                  <Input
                    type="number"
                    value={customMemberLimit}
                    onChange={(e) => setCustomMemberLimit(e.target.value)}
                    placeholder="Plan default"
                    className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  />
                </div>
                <div>
                  <label className="block text-zinc-400 mb-1">Trainer Limit</label>
                  <Input
                    type="number"
                    value={customTrainerLimit}
                    onChange={(e) => setCustomTrainerLimit(e.target.value)}
                    placeholder="Plan default"
                    className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  />
                </div>
                <div>
                  <label className="block text-zinc-400 mb-1">Staff Limit</label>
                  <Input
                    type="number"
                    value={customStaffLimit}
                    onChange={(e) => setCustomStaffLimit(e.target.value)}
                    placeholder="Plan default"
                    className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  />
                </div>
              </div>

              <div>
                <label className="block text-zinc-400 mb-1">Reason</label>
                <Input
                  value={actionReason}
                  onChange={(e) => setActionReason(e.target.value)}
                  placeholder="e.g. Custom agreement addendum"
                  className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  required
                />
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <Button type="button" variant="outline" onClick={() => setModalType(null)} className="text-xs">
                  Cancel
                </Button>
                <Button type="submit" disabled={actionLoading} className="bg-blue-600 hover:bg-blue-700 text-white text-xs">
                  {actionLoading ? "Saving..." : "Save Overrides"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* STATUS TOGGLE MODAL */}
      {modalType === "status" && selectedGym && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <div className="bg-zinc-950 border border-zinc-800 rounded-2xl p-6 max-w-md w-full shadow-2xl space-y-4 text-white">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
              <h3 className="font-bold text-base flex items-center gap-2 text-rose-400">
                <AlertTriangle className="w-5 h-5" />
                {statusAction === "suspended" ? "Suspend Subscription" : "Reactivate Subscription"}
              </h3>
              <button onClick={() => setModalType(null)} className="text-zinc-400 hover:text-white">
                <X className="w-4 h-4" />
              </button>
            </div>

            <p className="text-xs text-zinc-300">
              {statusAction === "suspended"
                ? `Suspending will block all feature and capacity operations for ${selectedGym.workspace_name}.`
                : `Reactivating will restore plan entitlements for ${selectedGym.workspace_name}.`}
            </p>

            <form onSubmit={handleStatusSubmit} className="space-y-4 text-xs">
              <div>
                <label className="block text-zinc-400 mb-1">Reason for Status Change</label>
                <Input
                  value={actionReason}
                  onChange={(e) => setActionReason(e.target.value)}
                  placeholder="Required administrative reason"
                  className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  required
                />
              </div>

              <div className="flex justify-end gap-2 pt-2">
                <Button type="button" variant="outline" onClick={() => setModalType(null)} className="text-xs">
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={actionLoading}
                  className={`${
                    statusAction === "suspended" ? "bg-rose-600 hover:bg-rose-700" : "bg-emerald-600 hover:bg-emerald-700"
                  } text-white text-xs`}
                >
                  {actionLoading ? "Updating..." : `Confirm ${statusAction.toUpperCase()}`}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* HISTORY / AUDIT MODAL */}
      {modalType === "history" && selectedGym && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <div className="bg-zinc-950 border border-zinc-800 rounded-2xl p-6 max-w-2xl w-full shadow-2xl space-y-4 text-white max-h-[85vh] flex flex-col">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
              <h3 className="font-bold text-base flex items-center gap-2 text-zinc-200">
                <History className="w-5 h-5 text-emerald-400" />
                Subscription History & Audit Log — {selectedGym.workspace_name}
              </h3>
              <button onClick={() => setModalType(null)} className="text-zinc-400 hover:text-white">
                <X className="w-4 h-4" />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto space-y-3 pr-2 text-xs">
              {detailedGymSub?.audit_logs?.length === 0 ? (
                <div className="py-8 text-center text-zinc-500">No administrative changes recorded for this workspace.</div>
              ) : (
                detailedGymSub?.audit_logs?.map((log: any) => (
                  <div key={log.id} className="p-3 bg-zinc-900 rounded-xl border border-zinc-800/80 space-y-1">
                    <div className="flex items-center justify-between font-mono text-[10px] text-zinc-400">
                      <span className="font-bold text-emerald-400 uppercase">{log.action}</span>
                      <span>{new Date(log.created_at).toLocaleString()}</span>
                    </div>
                    <div className="text-zinc-200 text-xs">{log.reason || "No reason specified"}</div>
                    <div className="text-[10px] text-zinc-400 font-mono">
                      {log.old_value && <span>Old: {log.old_value} → </span>}
                      {log.new_value && <span className="text-white">New: {log.new_value}</span>}
                    </div>
                  </div>
                ))
              )}
            </div>

            <div className="flex justify-end pt-2 border-t border-zinc-800">
              <Button type="button" variant="outline" onClick={() => setModalType(null)} className="text-xs">
                Close
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* EDIT PLAN MODAL */}
      {modalType === "edit_plan" && editingPlan && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs">
          <div className="bg-zinc-950 border border-zinc-800 rounded-2xl p-6 max-w-md w-full shadow-2xl space-y-4 text-white">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
              <h3 className="font-bold text-base flex items-center gap-2 text-emerald-400">
                <Edit2 className="w-5 h-5" />
                Edit Plan: {editingPlan.name}
              </h3>
              <button onClick={() => setModalType(null)} className="text-zinc-400 hover:text-white">
                <X className="w-4 h-4" />
              </button>
            </div>

            <form onSubmit={handleEditPlanSubmit} className="space-y-3 text-xs">
              <div>
                <label className="block text-zinc-400 mb-1">Display Name</label>
                <Input
                  value={editingPlan.name}
                  onChange={(e) => setEditingPlan({ ...editingPlan, name: e.target.value })}
                  className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-zinc-400 mb-1">Monthly Price (₹)</label>
                  <Input
                    type="number"
                    value={editingPlan.monthly_price}
                    onChange={(e) => setEditingPlan({ ...editingPlan, monthly_price: e.target.value })}
                    className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  />
                </div>
                <div>
                  <label className="block text-zinc-400 mb-1">Annual Price (₹)</label>
                  <Input
                    type="number"
                    value={editingPlan.annual_price}
                    onChange={(e) => setEditingPlan({ ...editingPlan, annual_price: e.target.value })}
                    className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  />
                </div>
              </div>

              <div className="grid grid-cols-3 gap-2">
                <div>
                  <label className="block text-zinc-400 mb-1">Member Limit</label>
                  <Input
                    type="number"
                    value={editingPlan.member_limit}
                    onChange={(e) => setEditingPlan({ ...editingPlan, member_limit: e.target.value })}
                    className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  />
                </div>
                <div>
                  <label className="block text-zinc-400 mb-1">Trainer Limit</label>
                  <Input
                    type="number"
                    value={editingPlan.trainer_limit}
                    onChange={(e) => setEditingPlan({ ...editingPlan, trainer_limit: e.target.value })}
                    className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  />
                </div>
                <div>
                  <label className="block text-zinc-400 mb-1">Staff Limit</label>
                  <Input
                    type="number"
                    value={editingPlan.staff_limit}
                    onChange={(e) => setEditingPlan({ ...editingPlan, staff_limit: e.target.value })}
                    className="bg-zinc-900 border-zinc-800 text-xs text-white"
                  />
                </div>
              </div>

              <div className="flex items-center gap-2 pt-2">
                <input
                  type="checkbox"
                  id="planActive"
                  checked={editingPlan.is_active}
                  onChange={(e) => setEditingPlan({ ...editingPlan, is_active: e.target.checked })}
                  className="rounded border-zinc-700"
                />
                <label htmlFor="planActive" className="text-zinc-300">
                  Active for new purchases
                </label>
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t border-zinc-800">
                <Button type="button" variant="outline" onClick={() => setModalType(null)} className="text-xs">
                  Cancel
                </Button>
                <Button type="submit" disabled={actionLoading} className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs">
                  {actionLoading ? "Saving..." : "Save Plan Changes"}
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import { repsiApi } from "@/lib/api";
import {
  X,
  MessageCircle,
  Dumbbell,
  Ticket,
  Calendar,
  UserCheck,
  MapPin,
  HelpCircle,
  Send,
  CheckCircle2,
  ChevronLeft,
  Sparkles,
  ArrowRight,
  Clock,
  Phone,
  MessageSquare,
} from "lucide-react";

interface GymAssistantProps {
  website: any;
  gymName: string;
  plans: any[];
  trainers: any[];
  classes: any[];
  slug: string;
}

type ScreenType =
  | "menu"
  | "memberships"
  | "trial_booking"
  | "visit_booking"
  | "trainers"
  | "location"
  | "qa"
  | "human_chat"
  | "booking_success";

export function GymAssistantWidget({
  website,
  gymName,
  plans,
  trainers,
  classes,
  slug,
}: GymAssistantProps) {
  // Check if assistant is disabled in settings
  if (website?.assistant_enabled === false) {
    return null;
  }

  const assistantName = website?.assistant_name || "Gym Assistant";
  const welcomeMsg =
    website?.assistant_welcome ||
    `Hi! I'm your ${assistantName}. How can I help you today?`;
  const whatsappPhone =
    website?.assistant_whatsapp ||
    website?.phone ||
    "918667783321";
  const primaryColor = website?.primary_color || "#16A34A";

  const [isOpen, setIsOpen] = useState(false);
  const [hasDismissedBubble, setHasDismissedBubble] = useState(false);
  const [screen, setScreen] = useState<ScreenType>("menu");
  const [mascotMood, setMascotMood] = useState<string>("welcome");

  // Booking Flow State
  const [bookingType, setBookingType] = useState<"free_trial" | "visit">("free_trial");
  const [bookingDate, setBookingDate] = useState("Tomorrow");
  const [customDate, setCustomDate] = useState("");
  const [bookingTime, setBookingTime] = useState("5:00 PM");
  const [userName, setUserName] = useState("");
  const [userPhone, setUserPhone] = useState("");
  const [userGoal, setUserGoal] = useState("");
  const [submittingBooking, setSubmittingBooking] = useState(false);
  const [bookingConfirmedDetails, setBookingConfirmedDetails] = useState<any>(null);

  // Q&A State
  const [userQuestion, setUserQuestion] = useState("");
  const [qaMessages, setQaMessages] = useState<
    { sender: "user" | "bot"; text: string; action?: { label: string; screen: ScreenType } }[]
  >([
    {
      sender: "bot",
      text: `Ask me anything about ${gymName}! I can answer questions about pricing, membership options, personal training, hours, or facilities.`,
    },
  ]);
  const [submittingChatLead, setSubmittingChatLead] = useState(false);
  const [chatLeadSuccess, setChatLeadSuccess] = useState(false);

  // Mascot image selection based on context/mood
  const getMascotSrc = () => {
    switch (mascotMood) {
      case "weights":
        return "/mascot/fitness.png";
      case "calendar":
        return "/mascot/help.png";
      case "ticket":
        return "/mascot/membership.png";
      case "trainer":
        return "/mascot/members.png";
      case "success":
        return "/mascot/success.png";
      case "website":
        return "/mascot/website.png";
      default:
        return "/mascot/welcome.png";
    }
  };

  const openWithMood = (newScreen: ScreenType, mood: string) => {
    setMascotMood(mood);
    setScreen(newScreen);
  };

  const handleStartBooking = (type: "free_trial" | "visit") => {
    setBookingType(type);
    setMascotMood(type === "free_trial" ? "ticket" : "calendar");
    setScreen(type === "free_trial" ? "trial_booking" : "visit_booking");
  };

  const handleSubmitBooking = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userName.trim() || !userPhone.trim()) {
      alert("Please provide your name and contact phone number.");
      return;
    }

    setSubmittingBooking(true);
    const chosenDate = bookingDate === "Custom" ? customDate || "Upcoming Date" : bookingDate;

    try {
      await repsiApi.submitPublicLead(slug, {
        name: userName.trim(),
        phone: userPhone.trim(),
        booking_type: bookingType,
        preferred_date: chosenDate,
        preferred_time: bookingTime,
        message: userGoal ? `Goal: ${userGoal}` : undefined,
        source: bookingType === "free_trial" ? "Trial Booking" : "Visit Booking",
        source_page: "Gym Assistant",
      });

      setBookingConfirmedDetails({
        name: userName,
        phone: userPhone,
        date: chosenDate,
        time: bookingTime,
        type: bookingType === "free_trial" ? "Free Trial Workout" : "Gym Visit & Tour",
      });

      setMascotMood("success");
      setScreen("booking_success");
    } catch (err: any) {
      alert(err.message || "Failed to submit booking. Please try again or message via WhatsApp.");
    } finally {
      setSubmittingBooking(false);
    }
  };

  // Automated FAQ Answer Engine
  const handleAskQuestion = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userQuestion.trim()) return;

    const q = userQuestion.trim();
    const qLower = q.toLowerCase();
    const updated = [...qaMessages, { sender: "user" as const, text: q }];
    setUserQuestion("");

    // Answer matching
    if (qLower.includes("price") || qLower.includes("cost") || qLower.includes("fee") || qLower.includes("membership") || qLower.includes("plan") || qLower.includes("how much")) {
      const topPlan = plans?.[0];
      const answer = topPlan
        ? `Our memberships start from ₹${topPlan.price?.toLocaleString()} for ${topPlan.duration_months} month(s). We have ${plans.length} flexible plans with no hidden charges.`
        : `We offer competitive and affordable membership packages tailored to your schedule.`;
      updated.push({
        sender: "bot",
        text: `${answer} Would you like to view our full membership tiers?`,
        action: { label: "View Memberships", screen: "memberships" },
      });
      setMascotMood("ticket");
    } else if (qLower.includes("hour") || qLower.includes("time") || qLower.includes("open") || qLower.includes("close") || qLower.includes("sunday")) {
      const hours = website?.opening_hours || "Mon - Sat: 6:00 AM - 10:00 PM | Sun: 7:00 AM - 1:00 PM";
      updated.push({
        sender: "bot",
        text: `Our opening hours are:\n${hours}\n\nWould you like to book a visit or free trial session?`,
        action: { label: "Book Free Trial", screen: "trial_booking" },
      });
      setMascotMood("calendar");
    } else if (qLower.includes("trainer") || qLower.includes("personal training") || qLower.includes("coach") || qLower.includes("pt")) {
      const trainerCount = trainers?.length || 0;
      updated.push({
        sender: "bot",
        text: `Yes! We have certified personal trainers specializing in fat loss, muscle building, and strength conditioning (${trainerCount > 0 ? `${trainerCount} dedicated coaches on site` : "certified fitness coaches"}).`,
        action: { label: "View Trainers", screen: "trainers" },
      });
      setMascotMood("trainer");
    } else if (qLower.includes("location") || qLower.includes("where") || qLower.includes("address") || qLower.includes("near")) {
      const addr = website?.address || "Coimbatore, Tamil Nadu";
      updated.push({
        sender: "bot",
        text: `We are located at:\n${addr}.\n\nFeel free to drop by or contact us anytime!`,
        action: { label: "View Contact & Map", screen: "location" },
      });
      setMascotMood("welcome");
    } else if (qLower.includes("trial") || qLower.includes("free") || qLower.includes("demo")) {
      updated.push({
        sender: "bot",
        text: `Yes! We offer a complimentary 1-day free trial so you can experience our facility, equipment, and community before deciding.`,
        action: { label: "Book Free Trial Now", screen: "trial_booking" },
      });
      setMascotMood("ticket");
    } else {
      // Human handoff recommendation
      updated.push({
        sender: "bot",
        text: `I want to make sure you get the exact right answer regarding that! Would you like to send a direct message to our gym team or talk on WhatsApp?`,
        action: { label: "Chat with Gym Team", screen: "human_chat" },
      });
      setMascotMood("calendar");
    }

    setQaMessages(updated);
  };

  const handleSendHumanChatLead = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userName.trim() || !userPhone.trim()) {
      alert("Please provide your name and contact phone number.");
      return;
    }
    setSubmittingChatLead(true);
    try {
      await repsiApi.submitPublicLead(slug, {
        name: userName.trim(),
        phone: userPhone.trim(),
        booking_type: "chat_handoff",
        message: userQuestion || "Requested chat callback via Assistant",
        source: "Website Chat",
        source_page: "Gym Assistant",
      });
      setChatLeadSuccess(true);
      setMascotMood("success");
    } catch (err: any) {
      alert(err.message || "Failed to submit request.");
    } finally {
      setSubmittingChatLead(false);
    }
  };

  const cleanWhatsappNumber = whatsappPhone.replace(/[^0-9]/g, "");
  const whatsappUrl = `https://wa.me/${cleanWhatsappNumber}?text=${encodeURIComponent(
    `Hi, I found ${gymName} through your website (repsi.app/${slug}). I'd like to ask a question or book a visit!`
  )}`;

  return (
    <div className="fixed bottom-5 right-5 z-50 font-sans">
      {/* Speech Bubble Tooltip when Assistant is closed */}
      {!isOpen && !hasDismissedBubble && (
        <div className="absolute bottom-20 right-0 mb-2 w-56 bg-zinc-900 border border-zinc-700/80 text-white p-3 rounded-2xl shadow-2xl animate-in fade-in slide-in-from-bottom-2 duration-300">
          <button
            onClick={(e) => {
              e.stopPropagation();
              setHasDismissedBubble(true);
            }}
            className="absolute top-1.5 right-1.5 text-zinc-400 hover:text-white p-1 rounded-full"
            aria-label="Dismiss greeting"
          >
            <X className="w-3.5 h-3.5" />
          </button>
          <div className="flex items-start gap-2.5">
            <MessageCircle className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
            <div>
              <p className="text-xs font-bold text-white leading-tight">
                Hi! Need gym info?
              </p>
              <p className="text-[11px] text-zinc-400 mt-0.5 leading-snug">
                Check plans, book a free trial, or chat with us.
              </p>
            </div>
          </div>
          {/* Arrow pointing down */}
          <div className="absolute -bottom-2 right-7 w-0 h-0 border-l-8 border-l-transparent border-r-8 border-r-transparent border-t-8 border-t-zinc-900" />
        </div>
      )}

      {/* Floating Mascot Trigger Button */}
      {!isOpen && (
        <button
          onClick={() => {
            setIsOpen(true);
            setHasDismissedBubble(true);
          }}
          className="group relative flex items-center justify-center w-16 h-16 rounded-full bg-zinc-950 border-2 border-emerald-500/50 shadow-2xl hover:scale-105 active:scale-95 transition-all duration-300"
          style={{ borderColor: primaryColor }}
          aria-label="Open Gym Assistant"
        >
          <div className="relative w-12 h-12 flex items-center justify-center">
            <Image
              src={getMascotSrc()}
              alt="Gym Assistant Mascot"
              width={48}
              height={48}
              className="object-contain drop-shadow-md group-hover:scale-110 transition-transform"
            />
          </div>
          {/* Online green indicator */}
          <span className="absolute bottom-0.5 right-0.5 w-3.5 h-3.5 bg-emerald-500 border-2 border-zinc-950 rounded-full animate-pulse" />
        </button>
      )}

      {/* Assistant Modal Window */}
      {isOpen && (
        <div className="w-[370px] sm:w-[400px] max-h-[85vh] h-[580px] bg-zinc-950/95 backdrop-blur-xl border border-zinc-800 rounded-3xl shadow-2xl flex flex-col overflow-hidden text-zinc-100 animate-in fade-in zoom-in-95 duration-200">
          {/* Header */}
          <div className="px-4 py-3.5 border-b border-zinc-800/80 bg-zinc-900/60 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="relative w-10 h-10 rounded-full bg-zinc-800 border border-zinc-700 flex items-center justify-center overflow-hidden">
                <Image
                  src={getMascotSrc()}
                  alt="Gym Assistant"
                  width={36}
                  height={36}
                  className="object-contain"
                />
                <span className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-emerald-500 border-2 border-zinc-900 rounded-full" />
              </div>
              <div>
                <h3 className="text-sm font-bold text-white flex items-center gap-1.5 leading-none">
                  {assistantName}
                  <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 font-medium">
                    Live
                  </span>
                </h3>
                <p className="text-[11px] text-zinc-400 mt-1 leading-none">{gymName}</p>
              </div>
            </div>

            <div className="flex items-center gap-1">
              {screen !== "menu" && (
                <button
                  onClick={() => {
                    setScreen("menu");
                    setMascotMood("welcome");
                  }}
                  className="p-1.5 text-zinc-400 hover:text-white rounded-lg hover:bg-zinc-800/60 transition"
                  title="Back to menu"
                >
                  <ChevronLeft className="w-4 h-4" />
                </button>
              )}
              <button
                onClick={() => setIsOpen(false)}
                className="p-1.5 text-zinc-400 hover:text-white rounded-lg hover:bg-zinc-800/60 transition"
                title="Close assistant"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          </div>

          {/* Body Content */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 text-xs">
            {/* SCREEN: MAIN MENU */}
            {screen === "menu" && (
              <div className="space-y-3.5">
                {/* Greeting Speech bubble */}
                <div className="p-3.5 rounded-2xl bg-zinc-900/90 border border-zinc-800 text-zinc-200">
                  <p className="font-medium text-white text-xs">{welcomeMsg}</p>
                </div>

                <p className="text-[11px] font-semibold text-zinc-400 uppercase tracking-wider px-1">
                  What can I help you with?
                </p>

                {/* Primary Action Buttons */}
                <div className="grid grid-cols-1 gap-2">
                  <button
                    onClick={() => openWithMood("memberships", "weights")}
                    className="flex items-center justify-between p-3 rounded-xl bg-zinc-900/70 hover:bg-zinc-800/90 border border-zinc-800 text-left transition group"
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-emerald-500/10 text-emerald-400 flex items-center justify-center font-bold text-base">
                        🏋️
                      </span>
                      <div>
                        <div className="font-semibold text-zinc-100 group-hover:text-white">
                          View Memberships
                        </div>
                        <div className="text-[11px] text-zinc-400">Plans, rates, and inclusions</div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-zinc-500 group-hover:text-emerald-400 transition" />
                  </button>

                  <button
                    onClick={() => handleStartBooking("free_trial")}
                    className="flex items-center justify-between p-3 rounded-xl bg-emerald-950/30 hover:bg-emerald-900/40 border border-emerald-500/30 text-left transition group"
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-emerald-500/20 text-emerald-300 flex items-center justify-center font-bold text-base">
                        🎟️
                      </span>
                      <div>
                        <div className="font-semibold text-emerald-300 group-hover:text-emerald-200 flex items-center gap-1.5">
                          Book Free Trial
                          <span className="text-[9px] px-1.5 py-0.5 rounded-full bg-emerald-500/20 text-emerald-300 font-bold uppercase">
                            Free
                          </span>
                        </div>
                        <div className="text-[11px] text-emerald-400/80">
                          Try our gym pass with 0 commitment
                        </div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-emerald-400 group-hover:translate-x-0.5 transition" />
                  </button>

                  <button
                    onClick={() => handleStartBooking("visit")}
                    className="flex items-center justify-between p-3 rounded-xl bg-zinc-900/70 hover:bg-zinc-800/90 border border-zinc-800 text-left transition group"
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-blue-500/10 text-blue-400 flex items-center justify-center font-bold text-base">
                        📅
                      </span>
                      <div>
                        <div className="font-semibold text-zinc-100 group-hover:text-white">
                          Book a Facility Visit
                        </div>
                        <div className="text-[11px] text-zinc-400">Tour gym & meet trainers</div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-zinc-500 group-hover:text-blue-400 transition" />
                  </button>

                  <button
                    onClick={() => openWithMood("trainers", "trainer")}
                    className="flex items-center justify-between p-3 rounded-xl bg-zinc-900/70 hover:bg-zinc-800/90 border border-zinc-800 text-left transition group"
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-purple-500/10 text-purple-400 flex items-center justify-center font-bold text-base">
                        👨‍🏫
                      </span>
                      <div>
                        <div className="font-semibold text-zinc-100 group-hover:text-white">
                          Certified Trainers
                        </div>
                        <div className="text-[11px] text-zinc-400">Personal coaching & bios</div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-zinc-500 group-hover:text-purple-400 transition" />
                  </button>

                  <button
                    onClick={() => openWithMood("location", "welcome")}
                    className="flex items-center justify-between p-3 rounded-xl bg-zinc-900/70 hover:bg-zinc-800/90 border border-zinc-800 text-left transition group"
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-amber-500/10 text-amber-400 flex items-center justify-center font-bold text-base">
                        📍
                      </span>
                      <div>
                        <div className="font-semibold text-zinc-100 group-hover:text-white">
                          Location & Hours
                        </div>
                        <div className="text-[11px] text-zinc-400">Address, schedule & phone</div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-zinc-500 group-hover:text-amber-400 transition" />
                  </button>

                  <button
                    onClick={() => openWithMood("qa", "calendar")}
                    className="flex items-center justify-between p-3 rounded-xl bg-zinc-900/70 hover:bg-zinc-800/90 border border-zinc-800 text-left transition group"
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-cyan-500/10 text-cyan-400 flex items-center justify-center font-bold text-base">
                        💬
                      </span>
                      <div>
                        <div className="font-semibold text-zinc-100 group-hover:text-white">
                          Ask a Question
                        </div>
                        <div className="text-[11px] text-zinc-400">Instant answers or chat with team</div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-zinc-500 group-hover:text-cyan-400 transition" />
                  </button>

                  {/* WhatsApp Quick Action */}
                  <a
                    href={whatsappUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center justify-between p-3 rounded-xl bg-emerald-950/40 hover:bg-emerald-900/50 border border-emerald-500/30 text-left transition group"
                  >
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-emerald-500/20 text-emerald-400 flex items-center justify-center font-bold text-base">
                        💚
                      </span>
                      <div>
                        <div className="font-semibold text-emerald-300">
                          Chat on WhatsApp
                        </div>
                        <div className="text-[11px] text-zinc-400">Direct message our desk</div>
                      </div>
                    </div>
                    <ArrowRight className="w-4 h-4 text-emerald-400 group-hover:translate-x-0.5 transition" />
                  </a>
                </div>
              </div>
            )}

            {/* SCREEN: MEMBERSHIPS */}
            {screen === "memberships" && (
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <h4 className="font-bold text-sm text-white flex items-center gap-1.5">
                    <span>🏋️</span> Membership Plans
                  </h4>
                  <button
                    onClick={() => handleStartBooking("free_trial")}
                    className="text-[11px] text-emerald-400 hover:underline font-semibold"
                  >
                    Book Trial First →
                  </button>
                </div>

                {plans && plans.length > 0 ? (
                  <div className="space-y-2.5">
                    {plans.map((p, idx) => (
                      <div
                        key={p.id || idx}
                        className="p-3 rounded-xl bg-zinc-900/80 border border-zinc-800 space-y-2"
                      >
                        <div className="flex items-start justify-between">
                          <div>
                            <span className="font-bold text-white text-xs">{p.name}</span>
                            <p className="text-[10px] text-zinc-400">
                              {p.duration_months} Month{p.duration_months > 1 ? "s" : ""} Validity
                            </p>
                          </div>
                          <div className="text-right">
                            <div className="font-bold text-emerald-400 text-sm">
                              ₹{p.price?.toLocaleString()}
                            </div>
                            <span className="text-[9px] text-zinc-500">All access</span>
                          </div>
                        </div>
                        {p.description && (
                          <p className="text-[11px] text-zinc-300 leading-snug">{p.description}</p>
                        )}
                        <button
