"use client";

import { useEffect, useState, useMemo } from "react";
import Link from "next/link";
import {
  Clock,
  Sparkles,
  AlertTriangle,
  CheckCircle2,
  AlertCircle,
  ArrowRight,
  ShieldCheck,
  CreditCard,
  Lock,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { repsiApi } from "@/lib/api";

export interface TrialStatusData {
  workspace_id: string;
  status: string;
  is_trial: boolean;
  is_expired: boolean;
  is_paid: boolean;
  trial_started_at: string;
  trial_ends_at: string;
  trial_converted_at?: string | null;
  total_trial_days: number;
  days_remaining: number;
  hours_remaining: number;
  progress_pct: number;
  trial_state:
    | "active"
    | "reminder_7d"
    | "reminder_3d"
    | "warning_1d"
    | "hours_remaining"
    | "expired"
    | "paid"
    | "payment_pending"
    | "suspended";
  plan_code: string;
  plan_name: string;
  member_limit: number;
  is_complimentary: boolean;
  can_upgrade: boolean;
  server_time_utc: string;
}

export function TrialCountdownCard({
  workspace,
  initialData,
}: {
  workspace: string;
  initialData?: TrialStatusData | null;
}) {
  const [data, setData] = useState<TrialStatusData | null>(initialData || null);
  const [loading, setLoading] = useState<boolean>(!initialData);
  const [currentTime, setCurrentTime] = useState<number>(Date.now());

  useEffect(() => {
    let isMounted = true;
    async function loadStatus() {
      try {
        const res = await repsiApi.getTrialStatus(workspace);
        if (isMounted) {
          setData(res);
          setLoading(false);
        }
      } catch (err) {
        console.warn("Trial status load note:", err);
        if (isMounted) setLoading(false);
      }
    }

    loadStatus();
    // Live polling every 60s for real-time status transitions
    const pollInterval = setInterval(loadStatus, 60_000);
    // 1-second ticker for smooth sub-hour countdown
    const ticker = setInterval(() => setCurrentTime(Date.now()), 1000);

    return () => {
      isMounted = false;
      clearInterval(pollInterval);
      clearInterval(ticker);
    };
  }, [workspace]);

  // Derived real-time countdown calculation
  const computedTiming = useMemo(() => {
    if (!data?.trial_ends_at) return { days: 0, hours: 0, minutes: 0, seconds: 0, isElapsed: false };

    const endMs = new Date(data.trial_ends_at).getTime();
    const diffMs = endMs - currentTime;

    if (diffMs <= 0) {
      return { days: 0, hours: 0, minutes: 0, seconds: 0, isElapsed: true };
    }

    const totalSeconds = Math.floor(diffMs / 1000);
    const days = Math.floor(totalSeconds / 86400);
    const hours = Math.floor((totalSeconds % 86400) / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    return { days, hours, minutes, seconds, isElapsed: false };
  }, [data?.trial_ends_at, currentTime]);

  if (loading || !data) {
    return null;
  }

  // Active Paid Subscription View
  if (data.is_paid && !data.is_trial) {
    return (
      <div className="rounded-2xl border border-emerald-500/20 bg-gradient-to-r from-emerald-500/5 via-emerald-500/10 to-teal-500/5 dark:border-emerald-500/30 p-4 sm:p-5 shadow-xs">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold">
              <CheckCircle2 className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span className="text-xs font-bold uppercase tracking-wider text-emerald-700 dark:text-emerald-400">
                  {data.plan_name} Plan Active
                </span>
                <span className="text-[10px] bg-emerald-500/20 text-emerald-800 dark:text-emerald-300 font-semibold px-2 py-0.5 rounded-full">
                  Subscription Live
                </span>
              </div>
              <p className="text-xs text-[#64748B] dark:text-[#94a3b8] mt-0.5">
                Up to {data.member_limit === -1 ? "Unlimited" : data.member_limit} members included.
              </p>
            </div>
          </div>
          <Link href={`/${workspace}/settings?tab=billing`}>
            <Button
              variant="outline"
              size="sm"
              className="border-emerald-500/30 text-emerald-700 dark:text-emerald-300 hover:bg-emerald-500/10 rounded-xl font-semibold text-xs"
            >
              <CreditCard className="w-3.5 h-3.5 mr-1.5" />
              Manage Billing
            </Button>
          </Link>
        </div>
      </div>
    );
  }

  // Expired Trial View
  if (data.is_expired || computedTiming.isElapsed) {
    return (
      <div className="rounded-2xl border-2 border-rose-500/40 bg-gradient-to-r from-rose-50 via-white to-rose-50 dark:from-[#2a0e14] dark:via-[#1a080d] dark:to-[#2a0e14] p-5 sm:p-6 shadow-md">
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-5">
          <div className="flex items-start gap-4">
            <div className="w-12 h-12 rounded-2xl bg-rose-500/15 text-rose-600 dark:text-rose-400 flex items-center justify-center shrink-0">
              <AlertCircle className="w-6 h-6 stroke-[2.5]" />
            </div>
            <div className="space-y-1">
              <div className="flex items-center gap-2">
                <span className="text-[11px] font-black uppercase tracking-wider text-rose-700 dark:text-rose-400 bg-rose-500/10 px-2.5 py-0.5 rounded-md">
                  14-Day Free Trial Ended
                </span>
                <span className="text-xs text-[#64748B] dark:text-[#94a3b8]">
                  Expired on {new Date(data.trial_ends_at).toLocaleDateString()}
                </span>
              </div>
              <h3 className="text-lg font-black text-[#172033] dark:text-white">
                Your free trial has ended — choose a plan to continue
              </h3>
              <p className="text-xs sm:text-sm text-[#475569] dark:text-[#cbd5e1] max-w-xl">
                Your gym records, members, and payment history are safely preserved. Upgrade now to reactivate member registrations, QR check-ins, and staff workflows.
              </p>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-2.5 w-full md:w-auto shrink-0">
            <Link href={`/${workspace}/settings?tab=billing`}>
              <Button className="w-full sm:w-auto bg-rose-600 hover:bg-rose-700 text-white font-bold text-xs h-10 px-5 rounded-xl shadow-sm gap-1.5 cursor-pointer">
                <span>View Plans & Upgrade</span>
                <ArrowRight className="w-4 h-4" />
              </Button>
            </Link>
          </div>
        </div>
      </div>
    );
  }

  // Active Trial: Style configurations based on days/hours remaining
  const isLastDay = computedTiming.days === 0;
  const isThreeDaysOrLess = computedTiming.days <= 3;
  const isSevenDaysOrLess = computedTiming.days <= 7;

  // Theme configuration for the contextual trial banner
  let theme = {
    border: "border-emerald-500/30",
    bg: "bg-gradient-to-r from-emerald-50/80 via-white to-emerald-50/40 dark:from-[#061810] dark:via-[#091f15] dark:to-[#061810]",
    badgeBg: "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400 border border-emerald-500/25",
    accent: "text-emerald-700 dark:text-emerald-400",
    progress: "bg-emerald-600 dark:bg-emerald-500",
    btn: "bg-[#16A34A] hover:bg-[#15803D] text-white",
    icon: <Sparkles className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />,
    heading: `${computedTiming.days} ${computedTiming.days === 1 ? "day" : "days"} remaining in your 14-day free trial`,
    message: "Explore member management, QR attendance, trainer coaching, and automated billing before your trial ends.",
  };

  if (isLastDay) {
    theme = {
      border: "border-rose-500/40",
      bg: "bg-gradient-to-r from-rose-50/90 via-white to-orange-50/60 dark:from-[#240a10] dark:via-[#19080d] dark:to-[#240a10]",
      badgeBg: "bg-rose-500/15 text-rose-700 dark:text-rose-400 border border-rose-500/30 animate-pulse",
      accent: "text-rose-600 dark:text-rose-400",
      progress: "bg-rose-600",
      btn: "bg-rose-600 hover:bg-rose-700 text-white",
      icon: <Clock className="w-5 h-5 text-rose-600 animate-spin" />,
      heading: `Trial expires today (${computedTiming.hours}h ${computedTiming.minutes}m remaining)`,
      message: "Your free trial ends in less than 24 hours. Upgrade now to ensure zero interruption for your gym members.",
    };
  } else if (isThreeDaysOrLess) {
    theme = {
      border: "border-amber-500/40",
      bg: "bg-gradient-to-r from-amber-50/80 via-white to-amber-50/40 dark:from-[#221706] dark:via-[#191105] dark:to-[#221706]",
      badgeBg: "bg-amber-500/15 text-amber-700 dark:text-amber-400 border border-amber-500/30",
      accent: "text-amber-700 dark:text-amber-400",
      progress: "bg-amber-500",
      btn: "bg-amber-600 hover:bg-amber-700 text-white",
      icon: <AlertTriangle className="w-5 h-5 text-amber-600" />,
      heading: `${computedTiming.days} days remaining — time to choose your plan`,
      message: "Lock in your plan to keep attendance logs, member rosters, and coach assignments running seamlessly.",
    };
  } else if (isSevenDaysOrLess) {
    theme = {
      border: "border-sky-500/30",
      bg: "bg-gradient-to-r from-sky-50/70 via-white to-sky-50/30 dark:from-[#061524] dark:via-[#091b2e] dark:to-[#061524]",
      badgeBg: "bg-sky-500/10 text-sky-700 dark:text-sky-400 border border-sky-500/25",
      accent: "text-sky-700 dark:text-sky-400",
      progress: "bg-sky-500",
      btn: "bg-sky-600 hover:bg-sky-700 text-white",
      icon: <Clock className="w-5 h-5 text-sky-600" />,
      heading: `You are halfway through your 14-day free trial (${computedTiming.days} days left)`,
      message: "Test out trainer assignments, public website booking, and automated fee reminders before your trial ends.",
    };
  }

  const formattedExpiry = new Date(data.trial_ends_at).toLocaleString("en-IN", {
    dateStyle: "medium",
    timeStyle: "short",
  });

  return (
    <div className={`rounded-2xl border-2 ${theme.border} ${theme.bg} p-4 sm:p-6 shadow-sm transition-all`}>
      <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-5">
        <div className="space-y-2.5 max-w-2xl">
          <div className="flex flex-wrap items-center gap-2">
            <span className={`text-[11px] font-bold uppercase tracking-wider px-2.5 py-0.5 rounded-md ${theme.badgeBg}`}>
              14-Day Free Trial · {data.plan_name} Tier Unlocked
            </span>
            <span className="text-[11px] font-medium text-[#64748B] dark:text-[#94a3b8] flex items-center gap-1">
              <Clock className="w-3 h-3" />
              Expires: {formattedExpiry}
            </span>
          </div>

          <div className="space-y-1">
            <h3 className="text-xl sm:text-2xl font-black text-[#172033] dark:text-white tracking-tight flex items-center gap-2">
              {theme.heading}
            </h3>
            <p className="text-xs sm:text-sm text-[#4A5D52] dark:text-[#a1b3a9] font-medium">
              {theme.message}
            </p>
          </div>

          {/* Trial Progress Bar */}
          <div className="space-y-1.5 pt-1">
            <div className="flex items-center justify-between text-[11px] font-semibold text-[#64748B] dark:text-[#94a3b8]">
              <span>Trial Consumption</span>
              <span>{Math.round(data.progress_pct)}% completed</span>
            </div>
            <div className="w-full h-2.5 rounded-full bg-[#E2EBE5] dark:bg-[#1b2b21] overflow-hidden">
              <div
                className={`h-full ${theme.progress} rounded-full transition-all duration-700`}
                style={{ width: `${Math.min(100, Math.max(5, data.progress_pct))}%` }}
              />
            </div>
          </div>
        </div>

        {/* CTA Actions */}
        <div className="flex flex-col sm:flex-row lg:flex-col gap-2.5 w-full lg:w-auto shrink-0 pt-2 lg:pt-0">
          <Link href={`/${workspace}/settings?tab=billing`}>
            <Button className={`w-full ${theme.btn} font-bold text-xs h-10 px-5 rounded-xl shadow-sm cursor-pointer gap-1.5`}>
              <CreditCard className="w-3.5 h-3.5" />
              <span>View Plans & Upgrade</span>
              <ArrowRight className="w-3.5 h-3.5" />
            </Button>
          </Link>
          <div className="flex items-center justify-center gap-1 text-[11px] text-[#64748B] dark:text-[#94a3b8] font-medium">
            <ShieldCheck className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
            <span>No credit card required for trial</span>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { 
  CreditCard, 
  Smartphone, 
  Building2, 
  QrCode, 
  Copy, 
  Check, 
  Upload, 
  FileText, 
  CheckCircle2, 
  XCircle, 
  Clock, 
  AlertCircle, 
  AlertTriangle,
  Info,
  Loader2,
  X
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { 
  repsiApi, 
  ApiPaymentInstructions, 
  ApiPaymentSubmission 
} from "@/lib/api";

interface MemberFeePaymentDialogProps {
  invoice: {
    id: string;
    amount: number;
    amount_paid?: number;
    outstanding_balance?: number;
    due_date?: string;
    plan_name?: string;
  };
  onClose: () => void;
  onSuccess: () => void;
}

export function MemberFeePaymentDialog({ invoice, onClose, onSuccess }: MemberFeePaymentDialogProps) {
  const [step, setStep] = useState<"instructions" | "submit" | "submitted">("instructions");
  const [instructions, setInstructions] = useState<ApiPaymentInstructions | null>(null);
  const [loadingInstructions, setLoadingInstructions] = useState(true);
  const [instructionsError, setInstructionsError] = useState("");

  // Copy helpers
  const [copiedKey, setCopiedKey] = useState<string | null>(null);

  // Submission Form State
  const amountDue = invoice.outstanding_balance ?? (invoice.amount - (invoice.amount_paid || 0));
  const [amountPaid, setAmountPaid] = useState<number>(amountDue);
  const [paymentMethod, setPaymentMethod] = useState<"upi" | "qr" | "phone" | "bank_transfer">("upi");
  const [transactionRef, setTransactionRef] = useState("");
  const [receiptFile, setReceiptFile] = useState<File | null>(null);
  const [receiptPreview, setReceiptPreview] = useState<string | null>(null);
  const [notes, setNotes] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [createdSubmission, setCreatedSubmission] = useState<ApiPaymentSubmission | null>(null);

  useEffect(() => {
    async function fetchInstructions() {
      try {
        setLoadingInstructions(true);
        const data = await repsiApi.getInvoicePaymentInstructions(invoice.id);
        setInstructions(data);
      } catch (err: any) {
        setInstructionsError(err.message || "Failed to load payment instructions from gym.");
      } finally {
        setLoadingInstructions(false);
      }
    }
    fetchInstructions();
  }, [invoice.id]);

  const copyToClipboard = (text: string, key: string) => {
    navigator.clipboard.writeText(text);
    setCopiedKey(key);
    setTimeout(() => setCopiedKey(null), 2000);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (file.size > 10 * 1024 * 1024) {
        setSubmitError("File exceeds maximum allowed size (10MB).");
        return;
      }
      setReceiptFile(file);
      setSubmitError("");
      if (file.type.startsWith("image/")) {
        setReceiptPreview(URL.createObjectURL(file));
      } else {
        setReceiptPreview(null);
      }
    }
  };

  const handleSubmitProof = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitError("");

    if (!receiptFile) {
      setSubmitError("Please upload your payment receipt or transaction screenshot.");
      return;
    }

    if (amountPaid <= 0) {
      setSubmitError("Please enter a valid amount paid.");
      return;
    }

    setIsSubmitting(true);
    try {
      const res = await repsiApi.submitPaymentReceipt({
        invoice_id: invoice.id,
        amount_paid: amountPaid,
        payment_method: paymentMethod,
        transaction_reference: transactionRef.trim() || undefined,
        payment_date: new Date().toISOString(),
        receipt_file: receiptFile,
        notes: notes.trim() || undefined,
      });

      setCreatedSubmission(res);
      setStep("submitted");
      onSuccess();
    } catch (err: any) {
      setSubmitError(err.message || "Failed to submit receipt proof. Please check your network.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/75 backdrop-blur-xs">
      <div className="bg-zinc-950 rounded-2xl border border-zinc-800 p-6 max-w-xl w-full shadow-2xl space-y-5 text-zinc-100 max-h-[92vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
          <div className="flex items-center gap-2">
            <CreditCard className="w-5 h-5 text-emerald-500" />
            <div>
              <h3 className="font-bold text-sm">Pay Membership Fee</h3>
              <p className="text-[11px] text-zinc-400">Invoice #{invoice.id} • {invoice.plan_name || "Gym Membership"}</p>
            </div>
          </div>
          <button onClick={onClose} className="text-zinc-400 hover:text-white p-1">
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Amount Due Banner */}
        <div className="p-4 rounded-xl bg-gradient-to-r from-emerald-950/40 to-zinc-900 border border-emerald-500/30 flex items-center justify-between">
          <div>
            <span className="text-[11px] text-zinc-400 font-medium">Outstanding Balance</span>
            <p className="text-2xl font-bold text-emerald-400 mt-0.5">₹{amountDue.toLocaleString("en-IN")}</p>
          </div>
          <div className="text-right text-[11px] text-zinc-400">
            <span>Direct to Gym Account</span>
            <p className="text-emerald-500 font-semibold">Zero Gateway Charges</p>
          </div>
        </div>

        {/* STEP 1: PAYMENT INSTRUCTIONS */}
        {step === "instructions" && (
          <div className="space-y-4">
            {loadingInstructions ? (
              <div className="p-8 text-center space-y-2">
                <Loader2 className="w-6 h-6 animate-spin mx-auto text-emerald-500" />
                <p className="text-xs text-zinc-400">Loading gym payment details...</p>
              </div>
            ) : instructionsError ? (
              <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs">
                {instructionsError}
              </div>
            ) : instructions ? (
              <>
                {/* Reference Tag Highlight */}
                {instructions.narration_reference && (
                  <div className="p-3.5 rounded-xl border border-amber-500/30 bg-amber-500/10 flex items-center justify-between text-xs">
                    <div>
                      <span className="text-amber-400 font-semibold">Transfer Reference Code:</span>
                      <p className="font-mono font-bold text-white text-sm mt-0.5">{instructions.narration_reference}</p>
                      <p className="text-[10px] text-zinc-400 mt-0.5">Mention this code in your UPI remark or transfer note for faster verification.</p>
                    </div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => copyToClipboard(instructions.narration_reference!, "ref")}
                      className="h-8 px-2.5 bg-zinc-900 border-zinc-700 text-amber-400 hover:text-white text-xs gap-1"
                    >
                      {copiedKey === "ref" ? <Check className="w-3.5 h-3.5 text-emerald-400" /> : <Copy className="w-3.5 h-3.5" />}
                      {copiedKey === "ref" ? "Copied" : "Copy"}
                    </Button>
                  </div>
                )}

                {/* Available Methods Tabs/Panels */}
                <div className="space-y-3">
                  {/* UPI Section */}
                  {instructions.upi_id && (
                    <div className="p-3.5 rounded-xl bg-zinc-900 border border-zinc-800 space-y-2 text-xs">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2 font-semibold text-white">
                          <Smartphone className="w-4 h-4 text-emerald-500" />
                          <span>UPI Transfer (GPay / PhonePe / Paytm / BHIM)</span>
                        </div>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => copyToClipboard(instructions.upi_id!, "upi")}
                          className="h-7 px-2 bg-zinc-800 border-zinc-700 text-xs gap-1"
                        >
                          {copiedKey === "upi" ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
                          {copiedKey === "upi" ? "Copied" : "Copy UPI ID"}
                        </Button>
                      </div>
                      <div className="p-2.5 rounded bg-zinc-950 font-mono text-emerald-400 font-bold flex items-center justify-between">
                        <span>{instructions.upi_id}</span>
                        {instructions.account_name && (
                          <span className="text-zinc-400 font-sans text-[11px] font-normal">({instructions.account_name})</span>
                        )}
                      </div>
                    </div>
                  )}

                  {/* Merchant QR Section */}
                  {instructions.has_qr_code && (
                    <div className="p-3.5 rounded-xl bg-zinc-900 border border-zinc-800 space-y-2 text-xs">
                      <div className="flex items-center gap-2 font-semibold text-white">
                        <QrCode className="w-4 h-4 text-blue-500" />
                        <span>Gym Merchant QR Code</span>
                      </div>
                      <div className="p-3 rounded-lg bg-zinc-950 flex flex-col items-center justify-center">
                        <img
                          src={repsiApi.getMerchantQrUrl()}
                          alt="Gym QR Code"
                          className="max-h-48 max-w-full rounded-lg border border-zinc-800 shadow-md object-contain"
                        />
                        <span className="text-[10px] text-zinc-400 mt-2">Scan using any payment app (GPay, PhonePe, Paytm)</span>
                      </div>
                    </div>
                  )}

                  {/* Phone Payment Section */}
                  {instructions.payment_phone && (
                    <div className="p-3.5 rounded-xl bg-zinc-900 border border-zinc-800 space-y-2 text-xs">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2 font-semibold text-white">
                          <Smartphone className="w-4 h-4 text-indigo-400" />
                          <span>Payment Contact / Number</span>
                        </div>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => copyToClipboard(instructions.payment_phone!, "phone")}
                          className="h-7 px-2 bg-zinc-800 border-zinc-700 text-xs gap-1"
                        >
                          {copiedKey === "phone" ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
                          {copiedKey === "phone" ? "Copied" : "Copy Number"}
                        </Button>
                      </div>
                      <p className="font-mono text-white text-sm font-semibold">{instructions.payment_phone}</p>
                    </div>
                  )}

                  {/* Bank Transfer Section */}
                  {instructions.bank_details?.account_number && (
                    <div className="p-3.5 rounded-xl bg-zinc-900 border border-zinc-800 space-y-3 text-xs">
                      <div className="flex items-center gap-2 font-semibold text-white">
                        <Building2 className="w-4 h-4 text-amber-400" />
                        <span>Direct Bank Transfer (NEFT / IMPS / RTGS)</span>
                      </div>
                      <div className="grid grid-cols-2 gap-2 text-[11px]">
                        <div className="p-2 rounded bg-zinc-950">
                          <span className="text-zinc-500">Account Holder</span>
                          <p className="font-semibold text-white mt-0.5">{instructions.bank_details.account_holder_name}</p>
                        </div>
                        <div className="p-2 rounded bg-zinc-950">
                          <span className="text-zinc-500">Bank Name</span>
                          <p className="font-semibold text-white mt-0.5">{instructions.bank_details.bank_name}</p>
                        </div>
                        <div className="p-2 rounded bg-zinc-950 flex items-center justify-between">
                          <div>
                            <span className="text-zinc-500">Account Number</span>
                            <p className="font-mono font-semibold text-white mt-0.5">{instructions.bank_details.account_number}</p>
                          </div>
                          <button
                            type="button"
                            onClick={() => copyToClipboard(instructions.bank_details!.account_number, "bank_acc")}
                            className="text-zinc-400 hover:text-white p-1"
                          >
                            {copiedKey === "bank_acc" ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
                          </button>
                        </div>
                        <div className="p-2 rounded bg-zinc-950 flex items-center justify-between">
                          <div>
                            <span className="text-zinc-500">IFSC Code</span>
                            <p className="font-mono font-semibold text-white mt-0.5">{instructions.bank_details.ifsc_code}</p>
                          </div>
                          <button
                            type="button"
                            onClick={() => copyToClipboard(instructions.bank_details!.ifsc_code, "ifsc")}
                            className="text-zinc-400 hover:text-white p-1"
                          >
                            {copiedKey === "ifsc" ? <Check className="w-3 h-3 text-emerald-400" /> : <Copy className="w-3 h-3" />}
                          </button>
                        </div>
                      </div>
                    </div>
                  )}
                </div>

                {/* Important Notice */}
                <div className="p-3 rounded-lg bg-zinc-900/60 border border-zinc-800 text-[11px] text-zinc-400 flex items-start gap-2">
                  <Info className="w-4 h-4 text-zinc-400 shrink-0 mt-0.5" />
                  <span>
                    After completing the transfer in your payment app, take a screenshot of the successful payment page and click &quot;Submit Payment Proof&quot; below.
                  </span>
                </div>

                <div className="pt-2 flex items-center justify-end gap-2">
                  <Button variant="outline" size="sm" onClick={onClose} className="bg-zinc-900 border-zinc-800 text-xs">
                    Cancel
                  </Button>
                  <Button
                    size="sm"
                    onClick={() => setStep("submit")}
                    className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs"
                  >
                    I Have Paid → Submit Receipt
                  </Button>
                </div>
              </>
            ) : null}
          </div>
        )}

        {/* STEP 2: RECEIPT SUBMISSION FORM */}
        {step === "submit" && (
          <form onSubmit={handleSubmitProof} className="space-y-4">
            <div className="p-3 rounded-lg bg-zinc-900 border border-zinc-800 text-xs flex items-center justify-between">
              <span className="text-zinc-400">Paying for Invoice:</span>
              <span className="font-mono font-bold text-white">{invoice.id}</span>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-zinc-300">Amount Paid (₹)</label>
                <input
                  type="number"
                  value={amountPaid}
                  onChange={(e) => setAmountPaid(Number(e.target.value))}
                  className="w-full px-3 py-2 rounded-lg border border-zinc-700 bg-zinc-900 text-white text-xs font-mono font-bold focus:outline-none focus:border-emerald-500"
                  required
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-zinc-300">Payment Method Used</label>
                <select
                  value={paymentMethod}
                  onChange={(e) => setPaymentMethod(e.target.value as any)}
                  className="w-full px-3 py-2 rounded-lg border border-zinc-700 bg-zinc-900 text-white text-xs focus:outline-none focus:border-emerald-500"
                >
                  <option value="upi">UPI Transfer</option>
                  <option value="qr">Scanned Gym QR Code</option>
                  <option value="phone">Phone Payment (GPay/PhonePe)</option>
                  <option value="bank_transfer">Direct Bank Transfer</option>
                </select>
              </div>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-zinc-300">Transaction ID / UTR # (Optional)</label>
              <input
                type="text"
                placeholder="e.g. 428910284920 or UPI Ref ID"
                value={transactionRef}
                onChange={(e) => setTransactionRef(e.target.value)}
                className="w-full px-3 py-2 rounded-lg border border-zinc-700 bg-zinc-900 text-white text-xs font-mono focus:outline-none focus:border-emerald-500"
              />
            </div>

            {/* File Upload Area */}
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-zinc-300">
                Payment Receipt / Screenshot <span className="text-rose-400">*</span>
              </label>
              <div className="p-4 rounded-xl border border-dashed border-zinc-700 bg-zinc-900/50 flex flex-col items-center justify-center text-center space-y-2 cursor-pointer hover:border-emerald-500 transition-colors">
                <input
                  type="file"
                  id="receiptUpload"
                  accept="image/png,image/jpeg,image/webp,application/pdf"
                  onChange={handleFileChange}
                  className="hidden"
                />
                <label htmlFor="receiptUpload" className="cursor-pointer space-y-1">
                  <Upload className="w-6 h-6 mx-auto text-emerald-400" />
                  <p className="text-xs font-semibold text-zinc-200">
                    {receiptFile ? receiptFile.name : "Click to select receipt screenshot"}
                  </p>
                  <p className="text-[10px] text-zinc-500">PNG, JPG, WEBP, or PDF up to 10MB</p>
                </label>
              </div>

              {receiptPreview && (
                <div className="mt-2 p-2 rounded-lg bg-zinc-900 border border-zinc-800 flex items-center justify-center">
                  <img src={receiptPreview} alt="Screenshot Preview" className="max-h-40 rounded object-contain" />
                </div>
              )}
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-zinc-300">Note for Gym Staff (Optional)</label>
              <input
                type="text"
                placeholder="e.g. Paid via Nitheesh's HDFC account"
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
                className="w-full px-3 py-2 rounded-lg border border-zinc-700 bg-zinc-900 text-white text-xs focus:outline-none focus:border-emerald-500"
              />
            </div>

            {submitError && (
              <div className="p-3 rounded-lg bg-rose-500/10 border border-rose-500/30 text-rose-400 text-xs">
                {submitError}
              </div>
            )}

            <div className="p-3 rounded-lg bg-amber-500/10 border border-amber-500/20 text-[11px] text-zinc-300 flex items-start gap-2">
              <AlertTriangle className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />
              <span>
                <strong>Verification Notice:</strong> Submitting a receipt records your proof for verification. Gym floor access is activated once an authorized owner or trainer verifies and approves the payment.
              </span>
            </div>

            <div className="pt-2 flex items-center justify-between">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => setStep("instructions")}
                disabled={isSubmitting}
                className="bg-zinc-900 border-zinc-800 text-xs text-zinc-300"
              >
                ← Back to Details
              </Button>
              <Button
                type="submit"
                size="sm"
                disabled={isSubmitting || !receiptFile}
                className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs gap-1.5"
              >
                {isSubmitting ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    Submitting Proof...
                  </>
                ) : (
                  <>
                    <CheckCircle2 className="w-3.5 h-3.5" />
                    Submit Payment Receipt
                  </>
                )}
              </Button>
            </div>
          </form>
        )}

        {/* STEP 3: SUBMITTED SUCCESS BANNER */}
        {step === "submitted" && createdSubmission && (
          <div className="py-6 text-center space-y-4">
            <div className="w-12 h-12 rounded-full bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center mx-auto text-emerald-400">
              <CheckCircle2 className="w-6 h-6" />
            </div>

            <div>
              <h4 className="text-base font-bold text-white">Payment Receipt Submitted!</h4>
              <p className="text-xs text-zinc-400 mt-1 max-w-sm mx-auto">
                Your payment proof for invoice <span className="font-mono text-zinc-200">#{invoice.id}</span> has been securely recorded.
              </p>
            </div>

            <div className="p-3.5 rounded-xl bg-zinc-900 border border-zinc-800 text-xs text-left space-y-1.5 max-w-sm mx-auto">
              <div className="flex justify-between">
                <span className="text-zinc-500">Submitted Amount:</span>
                <span className="font-bold text-emerald-400">₹{(createdSubmission.amount_paid ?? createdSubmission.amount ?? 0).toLocaleString("en-IN")}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-zinc-500">Status:</span>
                <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-500/10 text-amber-500 border border-amber-500/20">
                  Pending Owner Verification
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-zinc-500">Submission Time:</span>
                <span className="text-zinc-300">{new Date(createdSubmission.submitted_at || createdSubmission.payment_date || createdSubmission.created_at || Date.now()).toLocaleTimeString()}</span>
              </div>
            </div>

            <p className="text-[11px] text-zinc-500 max-w-sm mx-auto">
              Your gym owner or authorized trainer has been notified to verify your transaction. Access will be activated automatically once approved.
            </p>

            <div className="pt-2">
              <Button
                onClick={onClose}
                className="bg-zinc-800 hover:bg-zinc-700 text-white font-semibold text-xs px-6"
              >
                Close & View Status
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { 
  CheckCircle2, 
  XCircle, 
  Clock, 
  Eye, 
  Search, 
  Filter, 
  RefreshCw, 
  AlertTriangle, 
  ExternalLink, 
  Receipt, 
  ShieldCheck, 
  Smartphone, 
  Building2, 
  QrCode,
  FileText,
  UserCheck,
  Check,
  X,
  Loader2
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  repsiApi, 
  ApiPaymentSubmission, 
  ApiMember 
} from "@/lib/api";

export function PaymentVerificationQueue() {
  const [submissions, setSubmissions] = useState<ApiPaymentSubmission[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterStatus, setFilterStatus] = useState<string>("pending_review");
  const [search, setSearch] = useState("");
  
  // Modal states
  const [selectedSub, setSelectedSub] = useState<ApiPaymentSubmission | null>(null);
  const [previewReceiptOpen, setPreviewReceiptOpen] = useState(false);
  const [approveConfirmOpen, setApproveConfirmOpen] = useState(false);
  const [rejectModalOpen, setRejectModalOpen] = useState(false);
  const [rejectionReason, setRejectionReason] = useState("");
  const [actionLoading, setActionLoading] = useState(false);
  const [actionError, setActionError] = useState("");
  const [actionSuccess, setActionSuccess] = useState("");

  const loadSubmissions = async () => {
    try {
      setLoading(true);
      const data = await repsiApi.getPaymentSubmissions(filterStatus === "all" ? undefined : filterStatus);
      setSubmissions(data);
    } catch (err: any) {
      console.error("Error loading submissions:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadSubmissions();
  }, [filterStatus]);

  const handleApprove = async () => {
    if (!selectedSub) return;
    setActionLoading(true);
    setActionError("");
    try {
      await repsiApi.approvePaymentSubmission(selectedSub.id);
      setActionSuccess(`Payment for invoice ${selectedSub.invoice_id} approved. Ledger recorded and member access activated!`);
      setApproveConfirmOpen(false);
      setSelectedSub(null);
      await loadSubmissions();
      // Notify other views
      window.dispatchEvent(new Event("repsi_storage_update"));
      setTimeout(() => setActionSuccess(""), 4000);
    } catch (err: any) {
      setActionError(err.message || "Approval failed. Please verify your permissions.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleReject = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSub) return;
    if (!rejectionReason.trim()) {
      setActionError("Please provide a specific rejection reason for the member.");
      return;
    }
    setActionLoading(true);
    setActionError("");
    try {
      await repsiApi.rejectPaymentSubmission(selectedSub.id, rejectionReason.trim());
      setActionSuccess(`Payment submission rejected. Notification sent to member.`);
      setRejectModalOpen(false);
      setSelectedSub(null);
      setRejectionReason("");
      await loadSubmissions();
      setTimeout(() => setActionSuccess(""), 4000);
    } catch (err: any) {
      setActionError(err.message || "Rejection failed. Please try again.");
    } finally {
      setActionLoading(false);
    }
  };

  const filtered = submissions.filter((s) => {
    const q = search.toLowerCase();
    return (
      s.invoice_id?.toLowerCase().includes(q) ||
      s.transaction_reference?.toLowerCase().includes(q) ||
      s.member_id?.toLowerCase().includes(q) ||
      s.payment_method?.toLowerCase().includes(q)
    );
  });

  const pendingCount = submissions.filter((s) => s.status === "pending_review").length;

  return (
    <div className="space-y-6">
      {/* Top Notification Banner */}
      {actionSuccess && (
        <div className="p-4 rounded-xl border border-emerald-500/30 bg-emerald-500/10 text-emerald-400 text-sm flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="w-5 h-5 shrink-0" />
            <span>{actionSuccess}</span>
          </div>
          <button onClick={() => setActionSuccess("")} className="text-emerald-400 hover:text-white text-xs">✕</button>
        </div>
      )}

      {/* Verification Stats & Notice */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="p-4 rounded-xl border border-[var(--border)] bg-[var(--surface)] shadow-xs">
          <div className="flex items-center justify-between">
            <span className="text-xs text-[var(--text-muted)] font-medium">Pending Review</span>
            <span className="flex h-2 w-2 rounded-full bg-amber-500 animate-pulse" />
          </div>
          <p className="text-2xl font-bold text-[var(--text)] mt-2">{pendingCount}</p>
          <span className="text-[11px] text-amber-500 font-medium">Awaiting Owner / Trainer verification</span>
        </div>

        <div className="p-4 rounded-xl border border-[var(--border)] bg-[var(--surface)] shadow-xs">
          <span className="text-xs text-[var(--text-muted)] font-medium">Status Separation</span>
          <p className="text-xs font-semibold text-[var(--text)] mt-2">Submitted → Approved → Activated</p>
          <span className="text-[11px] text-emerald-500 font-medium">Strict zero-trust manual verification</span>
        </div>

        <div className="p-4 rounded-xl border border-amber-500/20 bg-amber-500/5 shadow-xs">
          <div className="flex items-center gap-2 text-amber-500 text-xs font-semibold">
            <AlertTriangle className="w-4 h-4 shrink-0" />
            <span>Audit Notice</span>
          </div>
          <p className="text-[11px] text-zinc-400 mt-1">
            Manual approval confirms you verified funds in your bank/UPI statement. It records an immutable ledger entry.
          </p>
        </div>
      </div>

      {/* Filter and Search Bar */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-3">
        <div className="flex items-center gap-2 w-full sm:w-auto">
          {[
            { id: "pending_review", label: "Pending Review" },
            { id: "approved", label: "Approved" },
            { id: "rejected", label: "Rejected" },
            { id: "all", label: "All Submissions" },
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setFilterStatus(tab.id)}
              className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-colors ${
                filterStatus === tab.id
                  ? "bg-[var(--primary)] text-[var(--primary-foreground)] shadow-xs"
                  : "bg-[var(--surface)] border border-[var(--border)] text-[var(--text-muted)] hover:text-[var(--text)]"
              }`}
            >
              {tab.label}
              {tab.id === "pending_review" && pendingCount > 0 && (
                <span className="ml-1.5 px-1.5 py-0.2 rounded-full text-[10px] bg-amber-500 text-black font-bold">
                  {pendingCount}
                </span>
              )}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-2 w-full sm:w-auto">
          <div className="relative flex-1 sm:w-64">
            <input
              type="text"
              placeholder="Search invoice or UTR..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-8 pr-3 py-1.5 rounded-lg border border-[var(--border)] bg-[var(--background)] text-xs text-[var(--text)] focus:outline-none"
            />
            <Search className="w-3.5 h-3.5 text-[var(--text-muted)] absolute left-2.5 top-2" />
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={loadSubmissions}
            className="h-8 px-2.5 border-[var(--border)] text-[var(--text-muted)] hover:text-[var(--text)]"
          >
            <RefreshCw className={`w-3.5 h-3.5 ${loading ? "animate-spin" : ""}`} />
          </Button>
        </div>
      </div>

      {/* Submissions Table */}
      <div className="rounded-[12px] border border-[var(--border)] bg-[var(--surface)] shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-xs">
            <thead>
              <tr className="border-b border-[var(--border)] bg-[var(--surface-hover)] text-[var(--text-muted)] font-semibold uppercase tracking-wider">
                <th className="p-3.5">Submission Info</th>
                <th className="p-3.5">Invoice #</th>
                <th className="p-3.5">Amount Paid</th>
                <th className="p-3.5">Method & Reference</th>
                <th className="p-3.5">Date & Time</th>
                <th className="p-3.5">Status</th>
                <th className="p-3.5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[var(--border)]">
              {filtered.length > 0 ? (
                filtered.map((sub) => (
                  <tr key={sub.id} className="hover:bg-[var(--surface-hover)]/50 transition-colors">
                    <td className="p-3.5">
                      <div className="font-semibold text-[var(--text)] flex items-center gap-2">
                        <UserCheck className="w-3.5 h-3.5 text-[var(--text-muted)]" />
                        <span>Member: {sub.member_id.substring(0, 8)}...</span>
                      </div>
                      <span className="text-[10px] text-[var(--text-muted)] font-mono">Sub ID: {sub.id.substring(0, 8)}</span>
                    </td>

                    <td className="p-3.5 font-mono font-medium text-[var(--text-secondary)]">
                      {sub.invoice_id}
                    </td>

                    <td className="p-3.5">
                      <span className="font-mono font-bold text-emerald-500 text-sm">
                        ₹{(sub.amount_paid ?? sub.amount ?? 0).toLocaleString("en-IN")}
                      </span>
                    </td>

                    <td className="p-3.5">
                      <div className="flex items-center gap-1.5 font-medium text-[var(--text)]">
                        {sub.payment_method === "upi" ? (
                          <Smartphone className="w-3.5 h-3.5 text-emerald-500" />
                        ) : sub.payment_method === "qr" ? (
                          <QrCode className="w-3.5 h-3.5 text-blue-500" />
                        ) : (
                          <Building2 className="w-3.5 h-3.5 text-indigo-500" />
                        )}
                        <span className="uppercase">{sub.payment_method}</span>
                      </div>
                      {(sub.transaction_reference || sub.transaction_ref) && (
                        <span className="text-[10px] font-mono text-[var(--text-muted)] block">
                          Ref: {sub.transaction_reference || sub.transaction_ref}
                        </span>
                      )}
                    </td>

                    <td className="p-3.5 text-[var(--text-muted)]">
                      {new Date(sub.payment_date || sub.submitted_at || sub.created_at || Date.now()).toLocaleDateString("en-IN", {
                        day: "numeric",
                        month: "short",
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </td>

                    <td className="p-3.5">
                      {sub.status === "pending_review" && (
                        <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-amber-500/10 text-amber-500 border border-amber-500/20">
                          <Clock className="w-3 h-3" />
                          Pending Review
                        </span>
                      )}
                      {sub.status === "approved" && (
                        <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-emerald-500/10 text-emerald-500 border border-emerald-500/20">
                          <CheckCircle2 className="w-3 h-3" />
                          Approved
                        </span>
                      )}
                      {sub.status === "rejected" && (
                        <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-rose-500/10 text-rose-500 border border-rose-500/20" title={sub.rejection_reason || undefined}>
                          <XCircle className="w-3 h-3" />
                          Rejected
                        </span>
                      )}
                    </td>

                    <td className="p-3.5 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => {
                            setSelectedSub(sub);
                            setPreviewReceiptOpen(true);
                          }}
                          className="h-7 px-2 text-xs border-[var(--border)] text-[var(--text-secondary)] hover:text-[var(--text)] gap-1"
                        >
                          <Eye className="w-3 h-3" />
                          Receipt
                        </Button>

                        {sub.status === "pending_review" && (
                          <>
                            <Button
                              size="sm"
                              onClick={() => {
                                setSelectedSub(sub);
                                setApproveConfirmOpen(true);
                              }}
                              className="h-7 px-2.5 text-xs bg-emerald-600 hover:bg-emerald-700 text-white font-semibold gap-1"
                            >
                              <Check className="w-3 h-3" />
                              Approve
                            </Button>
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => {
                                setSelectedSub(sub);
                                setRejectionReason("");
                                setRejectModalOpen(true);
                              }}
                              className="h-7 px-2 text-xs border-rose-500/30 text-rose-400 hover:bg-rose-500/10 gap-1"
                            >
                              <X className="w-3 h-3" />
                              Reject
                            </Button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={7} className="p-8 text-center text-[var(--text-muted)] space-y-2">
                    <Receipt className="w-6 h-6 mx-auto opacity-40" />
                    <p className="text-xs font-semibold text-[var(--text)]">No submissions found</p>
                    <p className="text-[11px]">
                      {filterStatus === "pending_review"
                        ? "There are currently no manual payment receipts waiting for verification."
                        : "No matching payment submissions match the selected filter."}
                    </p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Receipt Preview Modal */}
      {previewReceiptOpen && selectedSub && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-xs">
          <div className="bg-zinc-950 rounded-2xl border border-zinc-800 p-6 max-w-xl w-full shadow-2xl space-y-4 text-zinc-100">
            <div className="flex items-center justify-between border-b border-zinc-800 pb-3">
              <div className="flex items-center gap-2">
                <Receipt className="w-5 h-5 text-emerald-500" />
                <h3 className="font-bold text-sm">Payment Receipt & Details</h3>
              </div>
              <button
                onClick={() => setPreviewReceiptOpen(false)}
                className="text-zinc-400 hover:text-white"
              >
                ✕
              </button>
            </div>

            <div className="grid grid-cols-2 gap-3 text-xs">
              <div className="p-3 rounded-lg bg-zinc-900 border border-zinc-800">
                <span className="text-zinc-400">Amount Paid</span>
                <p className="text-lg font-bold text-emerald-400 mt-1">₹{(selectedSub.amount_paid ?? selectedSub.amount ?? 0).toLocaleString("en-IN")}</p>
              </div>
              <div className="p-3 rounded-lg bg-zinc-900 border border-zinc-800">
                <span className="text-zinc-400">Payment Method</span>
                <p className="text-sm font-semibold capitalize text-white mt-1">{selectedSub.payment_method}</p>
              </div>
              <div className="p-3 rounded-lg bg-zinc-900 border border-zinc-800">
                <span className="text-zinc-400">Transaction ID / UTR</span>
                <p className="font-mono text-xs text-white mt-1">{selectedSub.transaction_reference || selectedSub.transaction_ref || "Not provided"}</p>
              </div>
              <div className="p-3 rounded-lg bg-zinc-900 border border-zinc-800">
                <span className="text-zinc-400">Submission Date</span>
                <p className="text-xs text-white mt-1">{new Date(selectedSub.submitted_at || selectedSub.payment_date || selectedSub.created_at || Date.now()).toLocaleString()}</p>
              </div>
            </div>

            {selectedSub.notes && (
              <div className="p-3 rounded-lg bg-zinc-900 border border-zinc-800 text-xs">
                <span className="text-zinc-400">Member Note:</span>
                <p className="text-zinc-200 mt-0.5">{selectedSub.notes}</p>
              </div>
            )}

            {/* Receipt Media Preview */}
            <div className="space-y-2">
              <span className="text-xs font-semibold text-zinc-300">Uploaded Receipt / Screenshot:</span>
              <div className="p-2 rounded-xl bg-zinc-900 border border-zinc-800 flex flex-col items-center justify-center min-h-[220px] max-h-[360px] overflow-auto">
                <img
                  src={repsiApi.getReceiptUrl(selectedSub.id)}
                  alt="Receipt Preview"
                  className="max-h-[340px] max-w-full rounded object-contain"
                  onError={(e) => {
                    // Fallback for PDF or broken link
                    (e.target as HTMLElement).style.display = "none";
                  }}
                />
                <div className="mt-3">
                  <a
                    href={repsiApi.getReceiptUrl(selectedSub.id)}
                    target="_blank"
                    rel="noreferrer"
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-zinc-800 hover:bg-zinc-700 text-xs text-zinc-200 font-medium transition-colors"
                  >
                    <ExternalLink className="w-3.5 h-3.5" />
                    Open Original Document (New Tab)
                  </a>
                </div>
              </div>
            </div>

            {selectedSub.status === "rejected" && selectedSub.rejection_reason && (
              <div className="p-3 rounded-lg bg-rose-500/10 border border-rose-500/30 text-xs text-rose-400">
                <span className="font-semibold">Rejection Reason: </span>
                {selectedSub.rejection_reason}
              </div>
            )}

            <div className="pt-2 flex justify-end gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setPreviewReceiptOpen(false)}
                className="bg-zinc-900 border-zinc-800 text-zinc-300 text-xs"
              >
                Close
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Approve Confirmation Modal */}
      {approveConfirmOpen && selectedSub && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-xs">
          <div className="bg-zinc-950 rounded-2xl border border-emerald-500/40 p-6 max-w-md w-full shadow-2xl space-y-4 text-zinc-100">
            <div className="flex items-center gap-2 text-emerald-400">
              <ShieldCheck className="w-5 h-5" />
              <h3 className="font-bold text-base">Approve Manual Payment</h3>
            </div>

            <p className="text-xs text-zinc-300">
              You are approving a payment of{" "}
              <span className="font-bold text-emerald-400">₹{(selectedSub.amount_paid ?? selectedSub.amount ?? 0).toLocaleString("en-IN")}</span> for invoice{" "}
              <span className="font-mono font-bold text-white">{selectedSub.invoice_id}</span>.
            </p>

            <div className="p-3 rounded-lg bg-emerald-500/10 border border-emerald-500/20 text-xs text-zinc-300 space-y-1.5">
              <p className="font-semibold text-emerald-400">Atomic Actions Upon Approval:</p>
              <ul className="list-disc list-inside space-y-0.5 text-zinc-400">
                <li>Creates official Payment ledger record</li>
                <li>Marks Invoice as fully paid</li>
                <li>Restores member attendance & active gym access</li>
                <li>Records immutable audit trail with reviewer ID</li>
              </ul>
            </div>

            {actionError && (
              <div className="p-3 rounded-lg bg-rose-500/10 border border-rose-500/30 text-xs text-rose-400">
                {actionError}
              </div>
            )}

            <div className="pt-2 flex items-center gap-2 justify-end">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setApproveConfirmOpen(false)}
                disabled={actionLoading}
                className="bg-zinc-900 border-zinc-800 text-zinc-300 text-xs"
              >
                Cancel
              </Button>
              <Button
                size="sm"
                onClick={handleApprove}
                disabled={actionLoading}
                className="bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs gap-1.5"
              >
                {actionLoading ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    Approving...
                  </>
                ) : (
                  <>
                    <Check className="w-3.5 h-3.5" />
                    Confirm & Activate Access
                  </>
                )}
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Reject Reason Modal */}
      {rejectModalOpen && selectedSub && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-xs">
          <form onSubmit={handleReject} className="bg-zinc-950 rounded-2xl border border-rose-500/40 p-6 max-w-md w-full shadow-2xl space-y-4 text-zinc-100">
            <div className="flex items-center gap-2 text-rose-400">
              <XCircle className="w-5 h-5" />
              <h3 className="font-bold text-base">Reject Payment Submission</h3>
            </div>

            <p className="text-xs text-zinc-300">
              Provide a clear reason why this payment proof was rejected. The member will be notified and given the option to re-submit valid proof.
            </p>

            <div className="space-y-2">
              <label className="text-xs font-semibold text-zinc-300">Rejection Reason</label>
              <textarea
                value={rejectionReason}
                onChange={(e) => setRejectionReason(e.target.value)}
                placeholder="e.g. UTR number not found in bank statement, screenshot illegible, or amount mismatch."
                className="w-full h-24 p-3 rounded-lg border border-zinc-700 bg-zinc-900 text-xs text-white focus:outline-none focus:border-rose-500"
                required
              />
            </div>

            {actionError && (
              <div className="p-3 rounded-lg bg-rose-500/10 border border-rose-500/30 text-xs text-rose-400">
                {actionError}
              </div>
            )}

            <div className="pt-2 flex items-center gap-2 justify-end">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => setRejectModalOpen(false)}
                disabled={actionLoading}
                className="bg-zinc-900 border-zinc-800 text-zinc-300 text-xs"
              >
                Cancel
              </Button>
              <Button
                type="submit"
                size="sm"
                disabled={actionLoading || !rejectionReason.trim()}
                className="bg-rose-600 hover:bg-rose-700 text-white font-bold text-xs gap-1.5"
              >
                {actionLoading ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    Rejecting...
                  </>
                ) : (
                  <>
                    <X className="w-3.5 h-3.5" />
                    Reject Submission
                  </>
                )}
              </Button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}
